function renderCheckInMode(){if(navigator.onLine&&offlineQueue().length)syncOfflineCheckIns();const passengers=state.trip.passengers;const stopIds=[...new Set(passengers.map(p=>p.pickupStopId))];if(!state.currentCheckinStop||!stopIds.includes(Number(state.currentCheckinStop)))state.currentCheckinStop=stopIds.find(id=>passengers.some(p=>p.pickupStopId===id&&!p.checkedIn&&p.attendanceStatus!=='no_show'))||stopIds[0];const stopId=Number(state.currentCheckinStop),atStop=passengers.filter(p=>p.pickupStopId===stopId),checked=atStop.filter(p=>p.checkedIn).length,overall=passengers.filter(p=>p.checkedIn).length,problems=atStop.filter(p=>p.paymentStatus!=='cash'||p.attendanceStatus==='no_show');const pct=atStop.length?Math.round(checked/atStop.length*100):0;$('#tabContent').innerHTML=`<div class="connection-banner ${navigator.onLine?'online':'offline'}" id="connectionBanner">${navigator.onLine?'● Online · ændringer gemmes med det samme':'● Offline · check-in gemmes lokalt og synkroniseres senere'}</div><section class="checkin-command"><div><small>AKTUELT OPSAMLINGSSTED</small><select id="checkinStop">${stopIds.map(id=>`<option value="${id}" ${id===stopId?'selected':''}>${esc(stopName(id))}</option>`).join('')}</select></div><div class="checkin-progress"><span><b>${checked}</b> af ${atStop.length} ved stoppestedet</span><div><i style="width:${pct}%"></i></div><small>${overall} af ${passengers.length} på hele turen</small></div><button class="primary" id="completeStop" ${!atStop.length?'disabled':''}>Afslut stoppested →</button></section>${tripCashCards()}<div class="checkin-alerts"><div><strong>${atStop.filter(p=>!p.checkedIn&&p.attendanceStatus!=='no_show').length}</strong><span>Afventer</span></div><div class="warning"><strong>${atStop.filter(p=>p.paymentStatus!=='cash').length}</strong><span>Ikke betalt</span></div><div class="danger"><strong>${atStop.filter(p=>p.attendanceStatus==='no_show').length}</strong><span>Udeblevet</span></div><button id="toggleProblems">Vis ${problems.length} opmærksomhedspunkter</button></div><label class="checkin-search">⌕<input id="checkinSearch" placeholder="Søg passager, telefon eller sæde"></label><div id="problemPanel" class="problem-panel" hidden>${problems.map(p=>`<button data-focus-passenger="${p.id}"><strong>${esc(p.name)}</strong><span>${p.paymentStatus!=='cash'?'Ikke betalt':'Udeblevet'}</span></button>`).join('')||'<p>Ingen problemer ved dette stoppested</p>'}</div><div class="checkin-sections">${checkinSection('Afventer',atStop.filter(p=>!p.checkedIn&&p.attendanceStatus!=='no_show'),'pending')}${checkinSection('Checket ind',atStop.filter(p=>p.checkedIn),'checked')}${checkinSection('Udeblevet',atStop.filter(p=>p.attendanceStatus==='no_show'),'noshow')}</div><div id="undoCheckin"></div>`;wireCheckInMode(stopIds)}
function checkinSection(title,passengers,kind){return`<section class="checkin-group ${kind}"><header><h3>${title}</h3><span>${passengers.length}</span></header><div>${passengers.map(checkinCard).join('')||'<p class="empty-small">Ingen passagerer</p>'}</div></section>`}
function checkinCard(p){return`<article class="checkin-card ${p.checkedIn?'is-checked':''} ${p.attendanceStatus==='no_show'?'is-noshow':''}" data-checkin-card="${p.id}" data-search="${esc(`${p.name} ${p.phone} ${p.seatNumber}`.toLowerCase())}"><div class="checkin-seat"><small>SÆDE</small><strong>${p.seatNumber}</strong></div><div class="checkin-person"><h3>${esc(p.name)}</h3><a href="tel:${esc(p.phone)}">${esc(p.phone)}</a><span>${esc(stopName(p.pickupStopId))} → ${esc(stopName(p.destinationStopId))}</span>${p.pendingSync?'<em>Afventer synkronisering</em>':''}</div><div class="checkin-payment ${p.paymentStatus==='cash'?'paid':'unpaid'}"><small>${p.paymentStatus==='cash'?'BETALT':'IKKE BETALT'}</small><strong>${p.paymentStatus==='cash'?money(p.cashAmount,p.paymentCurrency||'DKK'):'Kræver handling'}</strong></div><div class="checkin-actions">${!p.checkedIn?`<button class="check-button" data-fast-check="${p.id}">✓ Check ind</button>`:'<span class="checked-label">✓ Checket ind</span>'}${p.paymentStatus!=='cash'?`<button class="pay-button" data-pay-passenger="${p.id}">Registrer betaling</button>`:''}<a href="tel:${esc(p.phone)}" class="icon-action" title="Ring">☎</a>${!p.checkedIn&&p.attendanceStatus!=='no_show'?`<button class="icon-action" data-no-show="${p.id}" title="Udeblevet">×</button>`:''}<button class="icon-action" data-passenger-detail="${p.id}" title="Detaljer">•••</button></div></article>`}
function wireCheckInMode(stopIds){$('#checkinStop').onchange=e=>{state.currentCheckinStop=Number(e.target.value);renderTrip()};$('#checkinSearch').oninput=e=>{const value=e.target.value.toLowerCase();$$('[data-checkin-card]').forEach(card=>card.hidden=!card.dataset.search.includes(value))};$('#toggleProblems').onclick=()=>{$('#problemPanel').hidden=!$('#problemPanel').hidden};$$('[data-focus-passenger]').forEach(button=>button.onclick=()=>{const card=$(`[data-checkin-card="${button.dataset.focusPassenger}"]`);if(card){card.scrollIntoView({behavior:'smooth',block:'center'});card.classList.add('focus-pulse');setTimeout(()=>card.classList.remove('focus-pulse'),1500)}});$$('[data-fast-check]').forEach(button=>button.onclick=()=>performFastCheckIn(Number(button.dataset.fastCheck)));$$('[data-pay-passenger]').forEach(button=>button.onclick=()=>openPaymentDialog('passenger',Number(button.dataset.payPassenger)));$$('[data-no-show]').forEach(button=>button.onclick=()=>markNoShow(Number(button.dataset.noShow)));$$('[data-passenger-detail]').forEach(button=>button.onclick=()=>showPassengerDetail(Number(button.dataset.passengerDetail)));$('#completeStop').onclick=()=>{state.completedCheckinStops=state.completedCheckinStops||[];if(!state.completedCheckinStops.includes(state.currentCheckinStop))state.completedCheckinStops.push(state.currentCheckinStop);const index=stopIds.indexOf(Number(state.currentCheckinStop));state.currentCheckinStop=stopIds[index+1]||stopIds[0];toast('Stoppestedet er afsluttet');renderTrip()};showUndoCheckIn()}
async function performFastCheckIn(id){const passenger=state.trip.passengers.find(p=>p.id===id);try{if(!navigator.onLine)throw Error('offline');const updated=await api(`/api/trips/${state.trip.trip.id}/passengers`,{method:'PATCH',body:JSON.stringify({id,checkedIn:true})});Object.assign(passenger,updated);signalCheckIn();renderTrip()}catch(error){const offline=!navigator.onLine||/fetch|network|offline|load failed/i.test(error.message);if(!offline)return toast(error.message);passenger.checkedIn=true;passenger.attendanceStatus='checked_in';passenger.checkedInAt=new Date().toISOString();passenger.checkedInBy=state.user.id;passenger.checkedInByName=state.user.name;passenger.pendingSync=true;queueOfflineCheckIn({tripId:state.trip.trip.id,id,checkedIn:true});signalCheckIn();renderTrip()}}
function signalCheckIn(){navigator.vibrate?.(80);try{const audio=new(window.AudioContext||window.webkitAudioContext)(),osc=audio.createOscillator(),gain=audio.createGain();osc.frequency.value=660;gain.gain.value=.05;osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.09)}catch(_){}}
function showUndoCheckIn(){}
function offlineQueue(){try{return JSON.parse(localStorage.getItem('busops-checkin-queue')||'[]')}catch(_){return[]}}function queueOfflineCheckIn(item){const queue=offlineQueue();queue.push(item);localStorage.setItem('busops-checkin-queue',JSON.stringify(queue))}function removeOfflineCheckIn(id){localStorage.setItem('busops-checkin-queue',JSON.stringify(offlineQueue().filter(item=>item.id!==id)))}
async function syncOfflineCheckIns(){if(!navigator.onLine||state.syncingOffline)return;state.syncingOffline=true;const queue=offlineQueue(),remaining=[];for(const item of queue){try{const updated=await api(`/api/trips/${item.tripId}/passengers`,{method:'PATCH',body:JSON.stringify({id:item.id,checkedIn:item.checkedIn})});if(state.trip?.trip.id===item.tripId){const local=state.trip.passengers.find(p=>p.id===item.id);if(local)Object.assign(local,updated,{pendingSync:false})}}catch(_){remaining.push(item)}}localStorage.setItem('busops-checkin-queue',JSON.stringify(remaining));state.syncingOffline=false;if(queue.length&&!remaining.length)toast('Offline check-in er synkroniseret')}
window.addEventListener('online',()=>{syncOfflineCheckIns();if(state.tab==='checkin')renderTrip()});window.addEventListener('offline',()=>{if(state.tab==='checkin')renderTrip()});syncOfflineCheckIns();

showPassengerDetail = function(id){const p=state.trip.passengers.find(x=>x.id===id),status=p.attendanceStatus==='no_show'?'Udeblevet':p.checkedIn?'Checket ind':'Afventer',holder=p.cashHolderUserId?tripDriverName(p.cashHolderUserId):p.paymentLocation==='shop'?'Salgsbutikken':'–',history=[...(p.attendanceHistory||[])].reverse();$('#modalBody').innerHTML=`<h2>${esc(p.name)}</h2><p class="muted">Passagerdetaljer og check-in-historik</p><div class="detail-list"><div><span>Telefon</span><strong><a href="tel:${esc(p.phone)}">${esc(p.phone)}</a></strong></div><div><span>Rute</span><strong>${esc(stopName(p.pickupStopId))} → ${esc(stopName(p.destinationStopId))}</strong></div><div><span>Sæde</span><strong>${p.seatNumber} · ${esc(p.seatType)}</strong></div><div><span>Check-in</span><strong>${status}${p.checkedInAt?' · '+date(p.checkedInAt):''}</strong></div><div><span>Betaling</span><strong>${p.paymentStatus==='cash'?money(p.cashAmount,p.paymentCurrency||'DKK'):'Ikke betalt'}</strong></div><div><span>Pengene står hos</span><strong>${esc(holder)}</strong></div></div><h3 class="history-title">Hændelser</h3><div class="history-list">${history.length?history.map(event=>`<div><i class="${event.action}"></i><span>${event.action==='checked_in'?'Checket ind':event.action==='no_show'?'Markeret udeblevet':'Check-in fortrudt'}<small>${date(event.at)} · ${esc(tripDriverName(event.userId))}</small></span></div>`).join(''):'<p>Ingen check-in-hændelser endnu</p>'}</div>`;$('#modal').showModal()}

const wireCheckInBeforeStopPersistence=wireCheckInMode;
wireCheckInMode=function(stopIds){wireCheckInBeforeStopPersistence(stopIds);$('#completeStop').onclick=async()=>{const current=Number(state.currentCheckinStop),pending=state.trip.passengers.filter(p=>p.pickupStopId===current&&!p.checkedIn&&p.attendanceStatus!=='no_show').length;if(pending&&!confirm(`${pending} passagerer afventer stadig. Vil du afslutte stoppestedet?`))return;try{const updated=await api(`/api/trips/${state.trip.trip.id}`,{method:'PATCH',body:JSON.stringify({completedStopId:current})});state.trip.trip=updated;const index=stopIds.indexOf(current);state.currentCheckinStop=stopIds[index+1]||stopIds[0];toast('Stoppestedet er afsluttet');renderTrip()}catch(error){toast(error.message)}}};
const wireCheckInBeforeCompletedLabels=wireCheckInMode;wireCheckInMode=function(stopIds){wireCheckInBeforeCompletedLabels(stopIds);const completed=state.trip.trip.completedStopIds||[];[...$('#checkinStop').options].forEach(option=>{if(completed.includes(Number(option.value)))option.textContent=`✓ ${option.textContent}`})};

const tripRendererBeforeSettlements=renderTrip;
renderTrip=function(){tripRendererBeforeSettlements();const tabs=$('.tabs');if(tabs){const pending=(state.trip.settlements||[]).filter(s=>s.status==='pending').length;tabs.insertAdjacentHTML('beforeend',`<button class="tab ${state.tab==='settlements'?'active':''}" data-settlement-tab>Pengekasser ${pending?`<span class="tab-count attention">${pending}</span>`:''}</button>`);$('[data-settlement-tab]').onclick=()=>{state.tab='settlements';renderTrip()}}if(state.tab==='settlements'){$$('.tab').forEach(tab=>tab.classList.remove('active'));$('[data-settlement-tab]').classList.add('active');renderSettlementTab()}};

tripCashCards=function(){const trip=state.trip.trip,driverIds=[trip.primaryDriverId,trip.secondaryDriverId].filter(Boolean);return`<div class="cash-custody">${driverIds.map(id=>{const records=[...state.trip.passengers,...state.trip.baggage].filter(r=>r.cashHolderUserId===id&&!r.cashHandedOverAt),dkk=records.filter(r=>(r.paymentCurrency||'DKK')==='DKK').reduce((s,r)=>s+Number(r.cashAmount||0),0),eur=records.filter(r=>r.paymentCurrency==='EUR').reduce((s,r)=>s+Number(r.cashAmount||0),0);return`<div><span>Uafleverede kontanter hos</span><strong>${esc(tripDriverName(id))}</strong><b>${money(dkk,'DKK')} · ${money(eur,'EUR')}</b></div>`}).join('')}</div>`};

function renderSettlementTab(){const trip=state.trip.trip,all=state.trip.settlements||[],driverIds=[trip.primaryDriverId,trip.secondaryDriverId].filter(Boolean),visibleIds=state.user.role==='admin'?driverIds:[state.user.id];$('#tabContent').innerHTML=`<div class="settlement-intro"><div><small>KONTANTAFSTEMNING</small><h2>Aflevering fra chauffør til kontor</h2><p>Beløbene beregnes fra betalinger modtaget i bussen på denne tur. DKK og EUR afstemmes separat.</p></div><span>${esc(trip.title)}<b>${date(trip.departureAt)}</b></span></div><div class="settlement-drivers">${visibleIds.map(driverId=>settlementDriverCard(driverId,all)).join('')}</div><section class="panel settlement-history"><div class="panel-head"><h2>Afstemningshistorik</h2><small>${all.length} afstemninger</small></div>${all.length?`<div class="table-scroll"><table class="list"><thead><tr><th>Chauffør</th><th>Forventet</th><th>Afleveret</th><th>Difference</th><th>Status</th><th>Behandling</th></tr></thead><tbody>${[...all].reverse().map(settlementRow).join('')}</tbody></table></div>`:'<div class="empty">Ingen kontantafstemninger endnu</div>'}</section>`;wireSettlementTab()}
function settlementCash(driverId){const records=[...state.trip.passengers.map(r=>({record:r,kind:'passenger'})),...state.trip.baggage.map(r=>({record:r,kind:'baggage'}))].filter(item=>item.record.cashHolderUserId===driverId&&item.record.paymentLocation==='bus'&&!item.record.cashHandedOverAt);return{records,DKK:records.filter(i=>(i.record.paymentCurrency||'DKK')==='DKK').reduce((s,i)=>s+Number(i.record.cashAmount||0),0),EUR:records.filter(i=>i.record.paymentCurrency==='EUR').reduce((s,i)=>s+Number(i.record.cashAmount||0),0)}}
function settlementDriverCard(driverId,all){const cash=settlementCash(driverId),pending=all.find(s=>s.driverId===driverId&&s.status==='pending'),canSubmit=(state.user.role==='driver'&&state.user.id===driverId)||state.user.role==='admin';return`<section class="settlement-card"><header><div class="avatar">${esc(tripDriverName(driverId).split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div><small>Kontanter hos</small><h3>${esc(tripDriverName(driverId))}</h3></div>${pending?'<span class="settlement-status pending">Afventer godkendelse</span>':'<span class="settlement-status open">Ikke afleveret</span>'}</header><div class="expected-cash"><div><span>Forventet DKK</span><strong>${money(cash.DKK,'DKK')}</strong></div><div><span>Forventet EUR</span><strong>${money(cash.EUR,'EUR')}</strong></div><small>${cash.records.length} betalinger</small></div>${pending?`<div class="pending-settlement"><span>Indberettet</span><strong>${money(pending.delivered.DKK,'DKK')} · ${money(pending.delivered.EUR,'EUR')}</strong><small>${date(pending.submittedAt)}</small></div>`:cash.records.length&&canSubmit?`<form class="form settlement-form" data-settlement-form="${driverId}"><label>Afleveret DKK<input name="deliveredDKK" type="number" min="0" step="0.01" value="${cash.DKK}" required></label><label>Afleveret EUR<input name="deliveredEUR" type="number" min="0" step="0.01" value="${cash.EUR}" required></label><label class="wide">Forklaring ved difference<textarea name="note" placeholder="Valgfrit, hvis beløbet stemmer"></textarea></label><button class="primary wide">Indsend til godkendelse</button></form>`:'<div class="settlement-empty">Ingen uafstemte kontanter</div>'}</section>`}
function settlementRow(s){const diffDkk=Number(s.difference.DKK),diffEur=Number(s.difference.EUR),automatic=Boolean(s.automaticZero);return`<tr class="${automatic?'automatic-zero-row':''}"><td><strong>${esc(s.driverName)}</strong><br><small>${automatic?'Automatisk ved driftsafslutning':date(s.submittedAt)}</small></td><td>${money(s.expected.DKK,'DKK')}<br>${money(s.expected.EUR,'EUR')}</td><td>${money(s.delivered.DKK,'DKK')}<br>${money(s.delivered.EUR,'EUR')}</td><td class="${diffDkk||diffEur?'difference':'balanced'}">${money(diffDkk,'DKK')}<br>${money(diffEur,'EUR')}</td><td><span class="settlement-status ${s.status}">${automatic?'<i class="bi bi-check2"></i> Automatisk 0':s.status==='pending'?'Afventer':s.status==='approved'?'Godkendt':'Afvist'}</span></td><td>${state.user.role==='admin'&&s.status==='pending'?`<div class="review-actions"><button class="mini done" data-approve-settlement="${s.id}">Godkend</button><button class="mini danger" data-reject-settlement="${s.id}">Afvis</button></div>`:`<small>${automatic?'Systemet':s.reviewedByName?`${esc(s.reviewedByName)}<br>${date(s.reviewedAt)}`:'–'}</small>`}</td></tr>`}
function wireSettlementTab(){$$('[data-settlement-form]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const payload={driverId:Number(form.dataset.settlementForm),...Object.fromEntries(new FormData(form))};try{const settlement=await api(`/api/trips/${state.trip.trip.id}/settlements`,{method:'POST',body:JSON.stringify(payload)});state.trip.settlements.push(settlement);toast('Afstemningen er sendt til administratoren');renderTrip()}catch(error){toast(error.message)}});$$('[data-approve-settlement]').forEach(button=>button.onclick=()=>reviewSettlement(Number(button.dataset.approveSettlement),'approved'));$$('[data-reject-settlement]').forEach(button=>button.onclick=()=>reviewSettlement(Number(button.dataset.rejectSettlement),'rejected'))}
async function reviewSettlement(id,status){const reviewNote=status==='rejected'?prompt('Hvorfor afvises afstemningen?')||'Afvist af administrator':'';try{await api(`/api/trips/${state.trip.trip.id}/settlements`,{method:'PATCH',body:JSON.stringify({id,status,reviewNote})});state.trip=await api(`/api/trips/${state.trip.trip.id}`);toast(status==='approved'?'Afstemningen er godkendt. Pengene står nu på kontoret.':'Afstemningen er afvist');renderTrip()}catch(error){toast(error.message)}}

const passengerDetailBeforeSettlement=showPassengerDetail;showPassengerDetail=function(id){passengerDetailBeforeSettlement(id);const passenger=state.trip.passengers.find(p=>p.id===id);if(passenger?.cashHandedOverAt){const row=[...$$('.detail-list>div')].find(div=>div.querySelector('span')?.textContent==='Pengene står hos');if(row)row.querySelector('strong').textContent=`Kontoret · afleveret ${date(passenger.cashHandedOverAt)}`}};

const reportsBeforeOfficeCash=renderReports;renderReports=async function(){await reportsBeforeOfficeCash();if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;try{const report=await api('/api/reports');$('.finance-grid')?.insertAdjacentHTML('afterend',`<div class="office-cash"><div><span>Godkendt og afleveret til kontoret · DKK</span><strong>${money(report.summary.cashAtOffice.DKK,'DKK')}</strong></div><div><span>Godkendt og afleveret til kontoret · EUR</span><strong>${money(report.summary.cashAtOffice.EUR,'EUR')}</strong></div></div>`)}catch(error){toast(error.message)}};

const seatGridBeforeSetraPlan=seatGrid;
seatGrid=function(selectable=true){
  const isDouble=state.trip.trip.bus?.type==='double'||state.trip.trip.seatCount===84||state.trip.seats.length===84;
  if(!isDouble)return seatGridBeforeSetraPlan(selectable);
  const lower=state.trip.seats.filter(seat=>seat.deck==='lower').slice(0,22),upper=state.trip.seats.filter(seat=>seat.deck==='upper').slice(0,62);
  if(!upper.length){const all=[...state.trip.seats];lower.splice(0,lower.length,...all.slice(0,22));upper.push(...all.slice(22,84))}
  const selected=state.trip.seats.find(seat=>seat.number===state.selectedSeat);
  return`<section class="double-decker-map" aria-label="Sædeplan for dobbeltdækkerbus">
    <div class="setra-plan-heading"><div><small>DOBBELTDÆKKER · 84 SÆDER</small><h3>Vælg dit sæde på kortet</h3><p>Tryk på et grønt sæde for at vælge det.</p></div><div class="deck-capacity"><span>Overetage <b>62</b></span><span>Underetage <b>22</b></span></div></div>
    <div class="setra-decks">${renderSetraUpper(upper,selectable)}${renderSetraLower(lower,selectable)}</div>
    <div class="seat-selection-footer"><div class="legend setra-legend"><span><i class="dot"></i>Ledigt</span><span><i class="dot selected-dot"></i>Valgt</span><span><i class="dot occupied"></i>Optaget</span><span><i class="dot premium-dot"></i>Ekstra pris</span></div><strong>${selected?`Valgt: sæde ${selected.number} · ${selected.deck==='upper'?'overetage':'underetage'}${selected.surcharge?` · +${selected.surcharge} kr.`:''}`:'Intet sæde valgt'}</strong></div>
  </section>`
};
function renderSetraUpper(seats,selectable){return`<section class="setra-deck upper"><header><span class="deck-icon">▣</span><div><strong>Overetage</strong><small>62 sæder · front øverst</small></div></header><div class="setra-bus-shell upper-shell"><div class="setra-windshield">BUSSENS FRONT</div><div class="upper-front"><div class="facility stairs stair-lines">Trappe</div><div class="facility lounge">Panorama</div></div><div class="setra-seat-rows">${referenceSeatRows(seats,selectable)}</div><div class="upper-rear"><div class="facility rear-stairs stair-lines">Trappe</div><div class="facility emergency">Nødudgang</div></div><div class="setra-rear">BAGENDEN</div></div></section>`}
function renderSetraLower(seats,selectable){
  const tableSeats=seats.filter(seat=>seat.type==='table').slice(0,8),regular=seats.filter(seat=>seat.type!=='table');
  return`<section class="setra-deck lower"><header><span class="deck-icon">▣</span><div><strong>Underetage</strong><small>22 sæder · 2 borde</small></div></header><div class="setra-bus-shell lower-shell"><div class="setra-windshield">BUSSENS FRONT</div><div class="cockpit-row"><div class="facility driver">Chauffør</div><div class="facility guide">Guide</div><div class="facility stairs stair-lines">Trappe</div></div><div class="lower-front-layout"><div class="facility entrance stair-lines">Indgang</div><div class="facility luggage">Magasin</div></div><div class="table-zone"><div class="table-zone-title">2 BORDGRUPPER · 4 PERSONER VED HVERT BORD</div>${Array.from({length:2},(_,index)=>renderTableBay(tableSideSeats(tableSeats,index),selectable,index+1)).join('')}</div><div class="setra-seat-rows lower-rear-seats">${referenceSeatRows(regular,selectable)}</div><div class="lower-service-map"><div class="facility wc">Toilet</div><div class="facility kitchen">Køkken</div><div class="facility luggage-room">Bagagerum</div><div class="facility rear-stairs stair-lines">Trappe</div></div><div class="setra-rear">BAGENDEN</div></div></section>`
}
function tableSideSeats(seats,index){return index===0?[...seats.slice(0,2),...seats.slice(4,6)]:[...seats.slice(2,4),...seats.slice(6,8)]}
function renderTableBay(seats,selectable,index){return`<div class="table-bay table-bay-${index}"><div class="facing-pair top">${seats.slice(0,2).map(seat=>seatButton(seat,selectable)).join('')}</div><div class="table-symbol">BORD ${index}</div><div class="facing-pair bottom">${seats.slice(2,4).map(seat=>seatButton(seat,selectable)).join('')}</div></div>`}
function referenceSeatRows(seats,selectable){let html='';for(let i=0;i<seats.length;i+=4){const row=seats.slice(i,i+4);html+=`<div class="reference-seat-row"><div>${row.slice(0,2).map(seat=>seatButton(seat,selectable)).join('')}</div><span aria-hidden="true"></span><div>${row.slice(2,4).map(seat=>seatButton(seat,selectable)).join('')}</div></div>`}return html}

const tripRendererBeforeBusAssignment=renderTrip;renderTrip=function(){tripRendererBeforeBusAssignment();if(state.user.role!=='admin'||!state.trip?.trip||!(state.buses||[]).length)return;const trip=state.trip.trip;$('.detail-hero').insertAdjacentHTML('afterend',`<form class="trip-bus-assignment" id="tripBusAssignment"><label>Bus på denne tur<select name="busId">${state.buses.map(bus=>`<option value="${bus.id}" ${trip.busId===bus.id?'selected':''}>${esc(bus.name)} · ${esc(bus.registration)} · ${bus.type==='double'?'Dobbeltdækker 22/62':'Almindelig '+bus.seatCount}</option>`).join('')}</select></label><button class="mini">${trip.busId?'Skift bus':'Tilknyt bus'}</button><small>Dobbeltdækker aktiverer automatisk den nye 84-sæders plantegning.</small></form>`);$('#tripBusAssignment').onsubmit=async event=>{event.preventDefault();try{const updated=await api(`/api/trips/${trip.id}`,{method:'PATCH',body:JSON.stringify({busId:Number(event.target.busId.value)})});state.trip.trip=updated;state.trip.seats=await api(`/api/trips/${trip.id}/seats`);const overview=state.trips.find(t=>t.id===trip.id);if(overview)Object.assign(overview,updated);toast('Bussen og sædeplanen er opdateret');renderTrip()}catch(error){toast(error.message)}}};

const reportRendererBeforeProfitability=renderReports;renderReports=async function(){await reportRendererBeforeProfitability();if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;try{const report=await api('/api/reports');const pending=report.expenses.filter(e=>(e.status||'pending')==='pending');$('#view').insertAdjacentHTML('afterbegin',`<section class="economy-control"><div><small>ØKONOMISTYRING</small><h2>Resultat pr. tur</h2></div><div class="economy-filters"><label>Fra<input id="economyFrom" type="date"></label><label>Til<input id="economyTo" type="date"></label><label>Tur<select id="economyTrip"><option value="">Alle ture</option>${report.tripResults.map(t=>`<option value="${t.tripId}">${esc(t.title)} · ${new Date(t.departureAt).toLocaleDateString(appLocale())}</option>`).join('')}</select></label><label>Vis valuta<select id="economyCurrency"><option value="all">DKK og EUR</option><option value="DKK">Kun DKK</option><option value="EUR">Kun EUR</option></select></label><button class="mini" id="resetEconomy">Nulstil</button><button class="mini" id="exportEconomy">Eksportér CSV</button></div><div class="economy-totals"><div><span>Omsætning</span><strong id="filteredRevenue">–</strong></div><div><span>Godkendte udgifter</span><strong id="filteredExpenses">–</strong></div><div><span>Nettoresultat</span><strong id="filteredNet">–</strong></div><div><span>Gennemsnitlig belægning</span><strong id="filteredOccupancy">–</strong></div></div></section><section class="panel trip-profit-panel"><div class="panel-head"><h2>Rentabilitet pr. tur</h2><small id="profitResultCount"></small></div><div class="table-scroll"><table class="list profit-table"><thead><tr><th>Tur</th><th>Belægning</th><th>Omsætning</th><th>Godkendte udgifter</th><th>Afventer</th><th>Nettoresultat</th></tr></thead><tbody id="tripProfitBody"></tbody></table></div></section><section class="panel expense-approval-panel"><div class="panel-head"><h2>Udgifter til godkendelse</h2><small>${pending.length} afventer</small></div>${pending.length?`<div class="table-scroll"><table class="list"><thead><tr><th>Tur og chauffør</th><th>Udgift</th><th>Beløb</th><th>Kvittering</th><th>Handling</th></tr></thead><tbody>${pending.map(e=>`<tr><td><strong>${esc(e.tripTitle)}</strong><br><small>${date(e.expenseDate||e.departureAt)} · ${esc(e.createdByName)}</small></td><td>${esc(e.category)}<br><small>${esc(e.description)}</small></td><td><strong>${money(e.amount,e.currency)}</strong></td><td><a class="receipt-link" href="/api/expenses/${e.id}/receipt" target="_blank">Se bilag ↗</a></td><td><div class="review-actions"><button class="mini done" data-approve-expense="${e.id}">Godkend</button><button class="mini danger" data-reject-expense="${e.id}">Afvis</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Ingen udgifter afventer godkendelse</div>'}</section>`);wireAdvancedEconomy(report)}catch(error){toast(error.message)}};
function wireAdvancedEconomy(report){const apply=()=>renderProfitRows(report);['#economyFrom','#economyTo','#economyTrip','#economyCurrency'].forEach(selector=>$(selector).onchange=apply);$('#resetEconomy').onclick=()=>{$('#economyFrom').value='';$('#economyTo').value='';$('#economyTrip').value='';$('#economyCurrency').value='all';apply()};$('#exportEconomy').onclick=()=>exportEconomyCsv(filteredTripResults(report));$$('[data-approve-expense]').forEach(button=>button.onclick=()=>reviewExpense(Number(button.dataset.approveExpense),'approved'));$$('[data-reject-expense]').forEach(button=>button.onclick=()=>reviewExpense(Number(button.dataset.rejectExpense),'rejected'));apply()}
function filteredTripResults(report){const from=$('#economyFrom').value,to=$('#economyTo').value,tripId=Number($('#economyTrip').value||0);return report.tripResults.filter(row=>{const day=row.departureAt.slice(0,10);return(!from||day>=from)&&(!to||day<=to)&&(!tripId||row.tripId===tripId)})}
function renderProfitRows(report){const rows=filteredTripResults(report),currency=$('#economyCurrency').value;$('#tripProfitBody').innerHTML=rows.map(row=>profitRow(row,currency)).join('')||'<tr><td colspan="6" class="empty">Ingen ture i den valgte periode</td></tr>';$('#profitResultCount').textContent=`${rows.length} ture`;const currencies=currency==='all'?['DKK','EUR']:[currency],formatTotals=field=>currencies.map(code=>money(rows.reduce((sum,row)=>sum+Number(row[field][code]||0),0),code)).join(' · ');$('#filteredRevenue').textContent=formatTotals('revenue');$('#filteredExpenses').textContent=formatTotals('approvedExpenses');$('#filteredNet').textContent=formatTotals('net');$('#filteredOccupancy').textContent=rows.length?`${Math.round(rows.reduce((sum,row)=>sum+row.occupancy,0)/rows.length)} %`:'0 %'}
function profitRow(row,currency){const currencies=currency==='all'?['DKK','EUR']:[currency],values=field=>currencies.map(code=>money(row[field][code],code)).join('<br>');return`<tr><td><strong>${esc(row.title)}</strong><br><small>${date(row.departureAt)} · ${esc(row.busName)}</small></td><td><div class="occupancy-meter"><span style="width:${Math.min(row.occupancy,100)}%"></span></div><strong>${row.occupancy} %</strong><small>${row.passengers}/${row.seatCount} · ${row.unpaid} ubetalt</small></td><td>${values('revenue')}</td><td>${values('approvedExpenses')}</td><td class="pending-money">${values('pendingExpenses')}</td><td class="${currencies.some(code=>row.net[code]<0)?'negative-net':'positive-net'}"><strong>${values('net')}</strong></td></tr>`}
async function reviewExpense(id,status){let reviewNote='';if(status==='rejected'){const reason=prompt('Hvorfor afvises udgiften?');if(reason===null)return;reviewNote=reason}try{await api(`/api/expenses/${id}`,{method:'PATCH',body:JSON.stringify({status,reviewNote})});toast(status==='approved'?'Udgiften er godkendt':'Udgiften er afvist');renderReports()}catch(error){toast(error.message)}}
function exportEconomyCsv(rows){const header=['Tur','Dato','Bus','Passagerer','Kapacitet','Belægning %','Omsætning DKK','Omsætning EUR','Godkendte udgifter DKK','Godkendte udgifter EUR','Netto DKK','Netto EUR'],data=rows.map(r=>[r.title,r.departureAt,r.busName,r.passengers,r.seatCount,r.occupancy,r.revenue.DKK,r.revenue.EUR,r.approvedExpenses.DKK,r.approvedExpenses.EUR,r.net.DKK,r.net.EUR]),csv=[header,...data].map(row=>row.map(value=>`"${String(value).replace(/"/g,'""')}"`).join(';')).join('\r\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='salg-og-oekonomi.csv';link.click();URL.revokeObjectURL(url)}

const expenseRendererBeforeApprovalStatus=renderExpensesTab;renderExpensesTab=function(){expenseRendererBeforeApprovalStatus();const expenses=state.trip.expenses||[],table=$('#tabContent table.list');if(!table)return;const heading=document.createElement('th');heading.textContent='Godkendelse';table.querySelector('thead tr').insertBefore(heading,table.querySelector('thead th:last-child'));[...table.querySelectorAll('tbody tr')].forEach((row,index)=>{const expense=expenses[index],cell=row.insertCell(row.cells.length-1),status=expense.status||'pending';cell.innerHTML=`<span class="expense-status ${status}">${status==='approved'?'Godkendt':status==='rejected'?'Afvist':'Afventer'}</span>${expense.reviewNote?`<br><small>${esc(expense.reviewNote)}</small>`:''}`})};

// Gratis billetter er en afsluttet billetstatus uden betaling eller omsætning.
passengerForm=function(){return`<section class="panel"><div class="panel-head"><h2>Ny passager</h2></div><form class="form" id="passengerForm" style="padding:20px"><label>Navn<input name="name" required></label><label>Telefon<input name="phone" required></label><label>Fra<select name="pickupStopId">${stopOptions()}</select></label><label>Til<select name="destinationStopId">${stopOptions()}</select></label><label>Billetstatus<select name="paymentStatus"><option value="unpaid">Ikke betalt</option><option value="pay_dk">Betaler i DK</option><option value="pay_mk">Betaler i MK</option><option value="cash">Betalt kontant</option><option value="free">Gratis billet</option></select></label><label data-cash-ticket-field hidden>Valuta<select name="paymentCurrency"><option value="DKK">DKK – Danske kroner</option><option value="EUR">EUR – Euro</option></select></label><label data-cash-ticket-field hidden>Kontant beløb<input name="cashAmount" type="number" min="0.01" step="0.01" value="0"></label><label class="wide" data-free-ticket-field hidden>Begrundelse for gratis billet<input name="freeTicketReason" placeholder="F.eks. barn, medarbejder, kampagne eller særlig aftale"></label><div class="wide"><strong>Vælg sæde</strong>${seatGrid(true)}<input type="hidden" name="seatNumber"></div><button class="primary wide">Opret passager</button></form></section>`};

const wirePassengerFormBeforeFreeTickets=wirePassengerForm;wirePassengerForm=function(){wirePassengerFormBeforeFreeTickets();const form=$('#passengerForm');if(!form)return;const update=()=>{const status=form.paymentStatus.value,isCash=status==='cash',isFree=status==='free';$$('[data-cash-ticket-field]').forEach(field=>field.hidden=!isCash);$$('[data-free-ticket-field]').forEach(field=>field.hidden=!isFree);form.cashAmount.required=isCash;form.cashAmount.disabled=!isCash;form.paymentCurrency.disabled=!isCash;form.freeTicketReason.disabled=!isFree};form.paymentStatus.onchange=update;update()};

passengerRow=function(p){const status=p.attendanceStatus||(p.checkedIn?'checked_in':'pending'),statusText={pending:'Afventer',checked_in:'Checket ind',no_show:'Udeblevet'}[status],payment=p.paymentStatus==='cash'?`<span class="payment-status paid">${money(p.cashAmount,p.paymentCurrency||'DKK')}</span>`:p.paymentStatus==='free'?`<span class="payment-status free">Gratis billet</span>`:`<button class="mini payment-action" data-pay-passenger="${p.id}">Registrer betaling</button>`;return`<tr data-passenger-row data-search="${esc(`${p.name} ${p.phone} ${p.seatNumber}`.toLowerCase())}" data-attendance="${status}" data-payment="${p.paymentStatus}" data-pickup="${p.pickupStopId}"><td><strong>${esc(p.name)}</strong><br><a class="phone-link" href="tel:${esc(p.phone)}">${esc(p.phone)}</a></td><td>${esc(stopName(p.pickupStopId))}<br><small>til ${esc(stopName(p.destinationStopId))}</small></td><td><span class="seat-badge">${p.seatNumber}</span></td><td><span class="attendance ${status}">${statusText}</span></td><td>${payment}</td><td><div class="row-actions"><button class="mini ${p.checkedIn?'done':''}" data-check="${p.id}">${p.checkedIn?'✓ Inde':'Check ind'}</button>${!p.checkedIn&&status!=='no_show'?`<button class="icon-action" data-no-show="${p.id}" title="Markér udeblevet">×</button>`:''}<button class="icon-action" data-passenger-detail="${p.id}" title="Se detaljer">•••</button></div></td></tr>`};

const enhancedPassengerTabBeforeFreeTickets=renderEnhancedPassengerTab;renderEnhancedPassengerTab=function(){enhancedPassengerTabBeforeFreeTickets();const filter=$('#paymentFilter');if(filter&&!filter.querySelector('[value="free"]'))filter.insertAdjacentHTML('beforeend','<option value="free">Gratis billet</option>')};

checkinCard=function(p){const paymentClass=p.paymentStatus==='free'?'free':p.paymentStatus==='cash'?'paid':'unpaid',paymentTitle=p.paymentStatus==='free'?'GRATIS BILLET':p.paymentStatus==='cash'?'BETALT':'IKKE BETALT',paymentValue=p.paymentStatus==='free'?(p.freeTicketReason||'Ingen betaling'):p.paymentStatus==='cash'?money(p.cashAmount,p.paymentCurrency||'DKK'):'Kræver handling';return`<article class="checkin-card ${p.checkedIn?'is-checked':''} ${p.attendanceStatus==='no_show'?'is-noshow':''}" data-checkin-card="${p.id}" data-search="${esc(`${p.name} ${p.phone} ${p.seatNumber}`.toLowerCase())}"><div class="checkin-seat"><small>SÆDE</small><strong>${p.seatNumber}</strong></div><div class="checkin-person"><h3>${esc(p.name)}</h3><a href="tel:${esc(p.phone)}">${esc(p.phone)}</a><span>${esc(stopName(p.pickupStopId))} → ${esc(stopName(p.destinationStopId))}</span>${p.pendingSync?'<em>Afventer synkronisering</em>':''}</div><div class="checkin-payment ${paymentClass}"><small>${paymentTitle}</small><strong>${esc(paymentValue)}</strong></div><div class="checkin-actions">${!p.checkedIn?`<button class="check-button" data-fast-check="${p.id}">✓ Check ind</button>`:'<span class="checked-label">✓ Checket ind</span>'}${p.paymentStatus==='unpaid'?`<button class="pay-button" data-pay-passenger="${p.id}">Registrer betaling</button>`:''}<a href="tel:${esc(p.phone)}" class="icon-action" title="Ring">☎</a>${!p.checkedIn&&p.attendanceStatus!=='no_show'?`<button class="icon-action" data-no-show="${p.id}" title="Udeblevet">×</button>`:''}<button class="icon-action" data-passenger-detail="${p.id}" title="Detaljer">•••</button></div></article>`};

const checkInModeBeforeFreeTickets=renderCheckInMode;renderCheckInMode=function(){checkInModeBeforeFreeTickets();const passengers=state.trip.passengers,atStop=passengers.filter(p=>p.pickupStopId===Number(state.currentCheckinStop)),unpaid=atStop.filter(p=>p.paymentStatus==='unpaid').length;const warning=$('.checkin-alerts .warning strong');if(warning)warning.textContent=unpaid;$$('#problemPanel [data-focus-passenger]').forEach(button=>{const passenger=passengers.find(p=>p.id===Number(button.dataset.focusPassenger));if(passenger?.paymentStatus==='free'&&passenger.attendanceStatus!=='no_show')button.remove();else if(passenger?.paymentStatus==='free')button.querySelector('span').textContent='Udeblevet'});const remaining=$$('#problemPanel [data-focus-passenger]').length,toggle=$('#toggleProblems');if(toggle)toggle.textContent=`Vis ${remaining} opmærksomhedspunkter`};

const passengerDetailBeforeFreeTickets=showPassengerDetail;showPassengerDetail=function(id){passengerDetailBeforeFreeTickets(id);const passenger=state.trip.passengers.find(p=>p.id===id);if(passenger?.paymentStatus!=='free')return;const rows=[...$$('.detail-list>div')],paymentRow=rows.find(row=>row.querySelector('span')?.textContent==='Betaling'),holderRow=rows.find(row=>row.querySelector('span')?.textContent==='Pengene står hos');if(paymentRow)paymentRow.querySelector('strong').textContent=`Gratis billet${passenger.freeTicketReason?` · ${passenger.freeTicketReason}`:''}`;if(holderRow)holderRow.querySelector('strong').textContent='Ingen betaling'};

exportPassengerList=function(){const headings=['Navn','Telefon','Opsamling','Destination','Sæde','Check-in','Billetstatus','Begrundelse','Beløb','Valuta'],rows=state.trip.passengers.map(p=>[p.name,p.phone,stopName(p.pickupStopId),stopName(p.destinationStopId),p.seatNumber,p.checkedIn?'Checket ind':p.attendanceStatus==='no_show'?'Udeblevet':'Afventer',p.paymentStatus==='cash'?'Betalt':p.paymentStatus==='free'?'Gratis billet':'Ikke betalt',p.freeTicketReason||'',p.paymentStatus==='cash'?p.cashAmount:0,p.paymentStatus==='cash'?(p.paymentCurrency||'DKK'):'']);const csv=[headings,...rows].map(row=>row.map(value=>`"${String(value).replace(/"/g,'""')}"`).join(';')).join('\r\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`passagerliste-${state.trip.trip.id}.csv`;link.click();URL.revokeObjectURL(url)};

profitRow=function(row,currency){const currencies=currency==='all'?['DKK','EUR']:[currency],values=field=>currencies.map(code=>money(row[field][code],code)).join('<br>'),ticketDetails=`${row.passengers}/${row.seatCount} · ${row.unpaid} ubetalt${row.freeTickets?` · ${row.freeTickets} gratis`:''}`;return`<tr><td><strong>${esc(row.title)}</strong><br><small>${date(row.departureAt)} · ${esc(row.busName)}</small></td><td><div class="occupancy-meter"><span style="width:${Math.min(row.occupancy,100)}%"></span></div><strong>${row.occupancy} %</strong><small>${ticketDetails}</small></td><td>${values('revenue')}</td><td>${values('approvedExpenses')}</td><td class="pending-money">${values('pendingExpenses')}</td><td class="${currencies.some(code=>row.net[code]<0)?'negative-net':'positive-net'}"><strong>${values('net')}</strong></td></tr>`};

const reportsBeforeFreeTickets=renderReports;renderReports=async function(){await reportsBeforeFreeTickets();if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;try{const report=await api('/api/reports'),summary=$$('.finance-main span')[0];if(summary)summary.textContent=`${report.summary.paidTickets} betalt · ${report.summary.freeTickets} gratis · ${report.summary.unpaidTickets} ikke betalt`;const ticketPanel=[...$$('.report-section')].find(panel=>panel.querySelector('h2')?.textContent==='Solgte billetter');if(ticketPanel){[...ticketPanel.querySelectorAll('tbody tr')].forEach((row,index)=>{const ticket=report.tickets[index];if(!ticket||ticket.paymentStatus!=='free')return;row.cells[4].innerHTML='<span class="payment-status free">Gratis billet</span>';row.cells[5].innerHTML=`<strong>${esc(ticket.freeTicketReason||'–')}</strong>`})}}catch(error){toast(error.message)}};

const tripRendererBeforeDriverAssignment=renderTrip;renderTrip=function(){tripRendererBeforeDriverAssignment();if(state.user.role!=='admin'||!state.trip?.trip)return;const trip=state.trip.trip,locked=state.trip.passengers.some(passenger=>passenger.checkedIn||passenger.attendanceHistory?.some(event=>event.action==='checked_in')),driverOptions=(selectedId)=>state.drivers.map(driver=>`<option value="${driver.id}" ${driver.id===selectedId?'selected':''}>${esc(driver.name)}</option>`).join(''),secondaryOptions=`<option value="">Ingen sekundær chauffør</option>${driverOptions(trip.secondaryDriverId)}`;const panel=locked?`<section class="trip-driver-assignment locked"><div><small>CHAUFFØRER PÅ TUREN</small><strong>${esc(trip.primaryDriver||'Ikke valgt')}</strong><span>${trip.secondaryDriver?`Sekundær: ${esc(trip.secondaryDriver)}`:'Ingen sekundær chauffør'}</span></div><div class="assignment-lock">🔒 Chaufførerne er låst, fordi check-in er begyndt</div></section>`:`<form class="trip-driver-assignment" id="tripDriverAssignment"><div><small>CHAUFFØRER PÅ TUREN</small><strong>Skift chauffører</strong><span>Muligt indtil første passager er checket ind</span></div><label>Primær chauffør<select name="primaryDriverId" required>${driverOptions(trip.primaryDriverId)}</select></label><label>Sekundær chauffør<select name="secondaryDriverId">${secondaryOptions}</select></label><button class="mini">Gem chauffører</button></form>`;$('.detail-hero').insertAdjacentHTML('afterend',panel);const form=$('#tripDriverAssignment');if(!form)return;form.onsubmit=async event=>{event.preventDefault();if(event.target.primaryDriverId.value===event.target.secondaryDriverId.value)return toast('Primær og sekundær chauffør skal være forskellige');try{const updated=await api(`/api/trips/${trip.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});state.trip.trip=updated;const overview=state.trips.find(item=>item.id===trip.id);if(overview)Object.assign(overview,updated);toast('Chaufførerne på turen er opdateret');renderTrip()}catch(error){toast(error.message)}}};

// Salgschef: check-in ved alle stop med gæster; salg og bagage ved startstedet.
const roleUiBeforeSalesManager=roleUi;roleUi=function(){roleUiBeforeSalesManager();if(state.user.role==='sales_manager')$('#userRole').textContent='Salgschef'};

const salesManagerNav=document.createElement('button');salesManagerNav.className='nav admin-only';salesManagerNav.dataset.view='sales-managers';salesManagerNav.innerHTML='<span>Salgschefer</span>';driverNav.after(salesManagerNav);salesManagerNav.onclick=renderSalesManagers;

function renderSalesManagers(){activate('sales-managers');setTitle('Salgschefer','ADMINISTRATOR');const managers=state.salesManagers||[];$('#view').innerHTML=`<div class="grid2"><section class="panel"><div class="panel-head"><h2>Salgschefer i systemet</h2><small>${managers.length} salgschefer</small></div>${managers.length?managers.map(manager=>`<div class="stop-card"><div class="driver-profile"><span class="avatar">${esc(manager.name.split(' ').map(part=>part[0]).slice(0,2).join(''))}</span><div><strong>${esc(manager.name)}</strong><div class="muted">${esc(manager.email)}</div></div></div><div class="stop-actions"><button class="mini" data-edit-sales-manager="${manager.id}">Rediger</button><button class="mini danger" data-delete-sales-manager="${manager.id}">Slet</button></div></div>`).join(''):'<div class="empty">Ingen salgschefer er oprettet</div>'}</section><section class="panel"><div class="panel-head"><h2>Tilføj salgschef</h2></div><form class="form" id="salesManagerForm" style="padding:22px;display:grid"><label>Fulde navn<input name="name" required></label><label>E-mail<input name="email" type="email" required></label><label>Midlertidig adgangskode<input name="password" type="password" minlength="12" required><small>Mindst 12 tegn</small></label><button class="primary">Opret salgschef</button></form></section></div>`;$('#salesManagerForm').onsubmit=async event=>{event.preventDefault();try{const manager=await api('/api/sales-managers',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});state.salesManagers.push(manager);toast('Salgschefen er oprettet');renderSalesManagers()}catch(error){toast(error.message)}};$$('[data-edit-sales-manager]').forEach(button=>button.onclick=()=>editSalesManager(Number(button.dataset.editSalesManager)));$$('[data-delete-sales-manager]').forEach(button=>button.onclick=async()=>{const manager=managers.find(item=>item.id===Number(button.dataset.deleteSalesManager));if(!confirm(`Vil du slette ${manager.name}?`))return;try{await api(`/api/sales-managers/${manager.id}`,{method:'DELETE'});state.salesManagers=state.salesManagers.filter(item=>item.id!==manager.id);toast('Salgschefen er slettet');renderSalesManagers()}catch(error){toast(error.message)}})}

function editSalesManager(id){const manager=state.salesManagers.find(item=>item.id===id);$('#modalBody').innerHTML=`<h2>Rediger salgschef</h2><form class="form" id="editSalesManagerForm"><label class="wide">Fulde navn<input name="name" value="${esc(manager.name)}" required></label><label class="wide">E-mail<input name="email" type="email" value="${esc(manager.email)}" required></label><label class="wide">Ny adgangskode<input name="password" type="password" minlength="12" placeholder="Lad feltet være tomt for at beholde den nuværende"></label><button class="primary wide">Gem ændringer</button></form>`;$('#editSalesManagerForm').onsubmit=async event=>{event.preventDefault();try{const updated=await api(`/api/sales-managers/${manager.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});Object.assign(manager,updated);state.trips.forEach(trip=>{if(trip.salesManagerId===manager.id)trip.salesManager=manager.name});$('#modal').close();toast('Salgschefen er opdateret');renderSalesManagers()}catch(error){toast(error.message)}};$('#modal').showModal()}

const newTripBeforeSalesManager=$('#newTrip').onclick;$('#newTrip').onclick=()=>{newTripBeforeSalesManager();const form=$('#createTrip');if(!form||state.user.role!=='admin')return;const salesManagerOptions=`<option value="">Ingen salgschef på vagt</option>${(state.salesManagers||[]).map(manager=>`<option value="${manager.id}">${esc(manager.name)}${manager.salesOfficeName?` · ${esc(manager.salesOfficeName)}`:''}</option>`).join('')}`;form.querySelector('button').insertAdjacentHTML('beforebegin',`<label>Salgschef på vagt (valgfri)<select name="salesManagerId">${salesManagerOptions}</select><small>Alle salgschefer kan booke turen. Den valgte får også adgang til check-in og afgangsdrift.</small></label>`)};

openTrip=async function(id){try{state.trip=await api(`/api/trips/${id}`);const salesOnDuty=state.user.role==='sales_manager'&&state.trip.trip.salesManagerId===state.user.id;state.tab=state.user.role==='driver'||salesOnDuty?'checkin':'passengers';state.selectedSeat=null;state.currentCheckinStop=null;renderTrip()}catch(error){toast(error.message)}};

const enhancedPassengerTabBeforeSalesManager=renderEnhancedPassengerTab;renderEnhancedPassengerTab=function(){enhancedPassengerTabBeforeSalesManager();if(state.user.role!=='sales_manager')return;const layout=$('.passenger-layout');if(!layout||$('#passengerForm'))return;layout.insertAdjacentHTML('beforeend',passengerForm());const form=$('#passengerForm'),freeOption=form.paymentStatus.querySelector('[value="free"]');if(freeOption)freeOption.remove();form.paymentStatus.value='cash';wirePassengerForm();form.paymentStatus.dispatchEvent(new Event('change'))};

const renderTabBeforeSalesManager=renderTab;renderTab=function(){renderTabBeforeSalesManager();if(state.user.role==='sales_manager'&&state.tab==='baggage'&&!$('#baggageForm')){const layout=$('#tabContent .grid2');if(layout){const placeholder=[...layout.children].find(child=>child.querySelector('.empty'));if(placeholder)placeholder.remove();layout.insertAdjacentHTML('beforeend',baggageForm());const form=$('#baggageForm');form.paymentStatus.value='cash';wireBaggageForm()}}};

const paymentDialogBeforeSalesManager=openPaymentDialog;openPaymentDialog=function(kind,id){paymentDialogBeforeSalesManager(kind,id);if(state.user.role!=='sales_manager')return;const form=$('#paymentForm');if(!form)return;const onDuty=state.trip.trip.salesManagerId===state.user.id;form.paymentLocation.innerHTML=`<option value="shop">I min salgsbutik</option>${onDuty?'<option value="departure">Ved turens startsted</option>':''}`;$('.cash-holder-field')?.remove();form.querySelector('.payment-warning').insertAdjacentHTML('beforebegin',`<div class="sales-cash-note wide">Kontanterne registreres i din personlige salgschef-kasse${onDuty?' med det valgte betalingssted':''} og skal senere afstemmes med kontoret.</div>`)};

const tripDriverNameBeforeSalesManager=tripDriverName;tripDriverName=function(id){const trip=state.trip?.trip,manager=state.salesManagers?.find(item=>item.id===id),record=[...(state.trip?.passengers||[]),...(state.trip?.baggage||[])].find(item=>item.cashHolderUserId===id&&item.cashHolderUserName);if(manager)return manager.name;if(record)return record.cashHolderUserName;if(trip&&id===trip.salesManagerId)return trip.salesManager||'Salgschef';return tripDriverNameBeforeSalesManager(id)};

tripCashCards=function(){const trip=state.trip.trip,allStaff=[trip.primaryDriverId,trip.secondaryDriverId,trip.salesManagerId].filter(Boolean),staffIds=state.user.role==='sales_manager'?[state.user.id]:allStaff;return`<div class="cash-custody">${staffIds.map(id=>{const records=[...state.trip.passengers,...state.trip.baggage].filter(record=>record.cashHolderUserId===id&&!record.cashHandedOverAt),dkk=records.filter(record=>(record.paymentCurrency||'DKK')==='DKK').reduce((sum,record)=>sum+Number(record.cashAmount||0),0),eur=records.filter(record=>record.paymentCurrency==='EUR').reduce((sum,record)=>sum+Number(record.cashAmount||0),0);return`<div><span>Uafleverede kontanter hos</span><strong>${esc(tripDriverName(id))}</strong><b>${money(dkk,'DKK')} · ${money(eur,'EUR')}</b></div>`}).join('')}</div>`};

settlementCash=function(staffId){const records=[...state.trip.passengers.map(record=>({record,kind:'passenger'})),...state.trip.baggage.map(record=>({record,kind:'baggage'}))].filter(item=>item.record.cashHolderUserId===staffId&&['bus','departure','shop'].includes(item.record.paymentLocation)&&!item.record.cashHandedOverAt);return{records,DKK:records.filter(item=>(item.record.paymentCurrency||'DKK')==='DKK').reduce((sum,item)=>sum+Number(item.record.cashAmount||0),0),EUR:records.filter(item=>item.record.paymentCurrency==='EUR').reduce((sum,item)=>sum+Number(item.record.cashAmount||0),0)}};

settlementDriverCard=function(staffId,all){const cash=settlementCash(staffId),pending=all.find(settlement=>settlement.driverId===staffId&&settlement.status==='pending'),automatic=[...all].reverse().find(settlement=>settlement.driverId===staffId&&settlement.automaticZero),canSubmit=(['driver','sales_manager'].includes(state.user.role)&&state.user.id===staffId)||state.user.role==='admin',status=pending?'<span class="settlement-status pending">Afventer administrator</span>':cash.records.length?'<span class="settlement-status open">I personlig pengekasse</span>':automatic?'<span class="settlement-status approved"><i class="bi bi-check2"></i> Automatisk 0</span>':'<span class="settlement-status approved">Ingen kontanter</span>';return`<section class="settlement-card ${automatic&&!cash.records.length?'automatic-zero':''}"><header><div class="avatar">${esc(tripDriverName(staffId).split(' ').map(part=>part[0]).slice(0,2).join(''))}</div><div><small>Personlig pengekasse</small><h3>${esc(tripDriverName(staffId))}</h3></div>${status}</header><div class="expected-cash"><div><span>Saldo DKK</span><strong>${money(cash.DKK,'DKK')}</strong></div><div><span>Saldo EUR</span><strong>${money(cash.EUR,'EUR')}</strong></div><small>${cash.records.length} kontantposteringer · påvirker ikke turens afslutning</small></div>${pending?`<div class="pending-settlement"><span>Afregning sendt til administrator</span><strong>${money(pending.delivered.DKK,'DKK')} · ${money(pending.delivered.EUR,'EUR')}</strong><small>${date(pending.submittedAt)}</small></div>`:cash.records.length&&canSubmit?`<form class="form settlement-form" data-settlement-form="${staffId}"><div class="wide settlement-choice-note"><i class="bi bi-info-circle"></i><span><strong>To muligheder</strong><small>Overfør til en salgschef fra Min pengekasse, eller indsend beløbet her til administratorens godkendelse.</small></span></div><label>Afleveret DKK<input name="deliveredDKK" type="number" min="0" step="0.01" value="${cash.DKK}" required></label><label>Afleveret EUR<input name="deliveredEUR" type="number" min="0" step="0.01" value="${cash.EUR}" required></label><label class="wide">Forklaring ved difference<textarea name="note"></textarea></label><button class="primary wide"><i class="bi bi-send-check"></i> Indsend afregning til administrator</button></form>`:`<div class="settlement-empty automatic-zero-message"><i class="bi bi-check-circle-fill"></i><span><strong>${automatic?'Automatisk afstemt til 0':'Ingen kontanter at afstemme'}</strong><small>Der kræves ingen handling fra chaufføren.</small></span></div>`}</section>`};

renderSettlementTab=function(){const trip=state.trip.trip,all=state.trip.settlements||[],staffIds=[trip.primaryDriverId,trip.secondaryDriverId,trip.salesManagerId].filter(Boolean),visibleIds=state.user.role==='admin'?staffIds:[state.user.id];$('#tabContent').innerHTML=`<div class="settlement-intro"><div><small>KONTANTAFSTEMNING</small><h2>Aflevering fra personale til kontor</h2><p>Betalinger modtaget i bussen og ved startstedet afstemmes separat i DKK og EUR.</p></div><span>${esc(trip.title)}<b>${date(trip.departureAt)}</b></span></div><div class="settlement-drivers">${visibleIds.map(staffId=>settlementDriverCard(staffId,all)).join('')}</div><section class="panel settlement-history"><div class="panel-head"><h2>Afstemningshistorik</h2><small>${all.length} afstemninger</small></div>${all.length?`<div class="table-scroll"><table class="list"><thead><tr><th>Medarbejder</th><th>Forventet</th><th>Afleveret</th><th>Difference</th><th>Status</th><th>Behandling</th></tr></thead><tbody>${[...all].reverse().map(settlementRow).join('')}</tbody></table></div>`:'<div class="empty">Ingen kontantafstemninger endnu</div>'}</section>`;wireSettlementTab()};

