// A derived, read-only financial journal keeps revenue, expenses and money
// movements traceable without introducing a second editable source of truth.
const renderReportsBeforeFinancialLedger=renderReports;
renderReports=async function(){
  await renderReportsBeforeFinancialLedger();
  if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;
  try{
    const report=await api('/api/reports'),entries=report.ledger||[];
    const icons={revenue:'bi-arrow-down-left-circle',expense:'bi-arrow-up-right-circle',transfer:'bi-arrow-left-right',settlement:'bi-bank'};
    const labels={revenue:'Indtægt',expense:'Udgift',transfer:'Overførsel',settlement:'Afstemning'};
    $('#view').insertAdjacentHTML('beforeend',`<section class="financial-ledger card border-0 shadow-sm"><header><div><small>SPORBAR ØKONOMI</small><h2>Økonomisk journal</h2><p>Oprettes automatisk fra betalinger, godkendte udgifter og pengebevægelser.</p></div><span>${entries.length} posteringer</span></header>${entries.length?`<div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Dato</th><th>Type</th><th>Tur</th><th>Beskrivelse</th><th>Registreret af</th><th class="text-end">Beløb</th></tr></thead><tbody>${entries.map(entry=>`<tr><td><strong>${date(entry.at)}</strong></td><td><span class="ledger-kind ${entry.kind}"><i class="bi ${icons[entry.kind]||'bi-dot'}"></i>${labels[entry.kind]||entry.kind}</span></td><td>${esc(entry.tripTitle)}</td><td>${esc(entry.description)}</td><td>${esc(entry.actorName||'System')}</td><td class="text-end ledger-amount ${entry.signedAmount<0?'negative':entry.signedAmount>0?'positive':'neutral'}"><strong>${entry.signedAmount<0?'−':entry.signedAmount>0?'+':''}${money(entry.amount,entry.currency)}</strong>${entry.signedAmount===0?'<small>Ingen resultatpåvirkning</small>':''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Journalen er tom, indtil den første betaling eller godkendte udgift registreres.</div>'}</section>`);
  }catch(error){toast(error.message)}
};

// One operational lifecycle and one exception center bind the existing BusOps tools together.
const operationalPhaseOrder=['planned','boarding','underway','arrived','finance_pending','completed'];
const operationalPhaseLabels={planned:'Planlagt',ready:'Klar til check-in',boarding:'Check-in åbnet',underway:'Undervejs',arrived:'Ankommet',finance_pending:'Klar til afslutning',completed:'Afsluttet',cancelled:'Annulleret'};
function lifecycleStepState(phase,step){const normalized=phase==='ready'?'planned':phase,current=operationalPhaseOrder.indexOf(normalized),index=operationalPhaseOrder.indexOf(step);return current>index?'done':current===index?'active':''}
function operationalLifecyclePanel(trip){
  const phase=trip.operationalPhase||'planned',checklist=trip.departureChecklist||{},missingChecks=Object.values(checklist).filter(Boolean).length,canDrive=['admin','driver'].includes(state.user.role),canBoard=['admin','driver'].includes(state.user.role)||(state.user.role==='sales_manager'&&trip.salesManagerId===state.user.id);
  const checkInOpensAt=trip.checkInOpensAt||new Date(new Date(trip.departureAt).getTime()-60*60*1000).toISOString(),waitingForAutomaticCheckIn=['planned','ready'].includes(phase)&&new Date(checkInOpensAt)>new Date();
  const action=phase==='planned'||phase==='ready'?waitingForAutomaticCheckIn?`<span class="lifecycle-awaiting"><i class="bi bi-clock-history"></i> Åbner automatisk ${date(checkInOpensAt)}</span>`:canBoard?'<button class="btn btn-primary" data-operational-action="start_boarding"><i class="bi bi-person-walking"></i> Åbn check-in</button>':'' :phase==='boarding'&&canDrive?`<button class="btn btn-primary" data-operational-action="start_trip"><i class="bi bi-play-circle-fill"></i> Start tur</button>${missingChecks<5?`<button class="btn btn-outline-warning" data-open-departure><i class="bi bi-clipboard2-check"></i> ${5-missingChecks} kontroller mangler</button>`:''}`:phase==='underway'&&canDrive?'<button class="btn btn-success" data-operational-action="mark_arrived"><i class="bi bi-flag-fill"></i> Registrer ankomst</button>':phase==='arrived'?'<button class="btn btn-outline-primary" data-open-checkin><i class="bi bi-person-check-fill"></i> Afslut passagerlisten</button>':phase==='finance_pending'&&state.user.role==='driver'?'<button class="btn btn-success" data-close-operations><i class="bi bi-check2-circle"></i> Afslut turens drift</button>':phase==='finance_pending'?'<span class="lifecycle-awaiting"><i class="bi bi-check2-circle"></i> Driften er klar til afslutning</span>':'';
  const lifecycleNote=trip.arrivalSource==='schedule'?`<span class="automatic-arrival-note"><i class="bi bi-clock-history"></i><span>Ankomst registreret automatisk efter tidsplanen</span><time> · ${date(trip.arrivedAt)}</time></span>`:trip.startSource==='schedule'?`<span class="automatic-arrival-note"><i class="bi bi-clock-history"></i><span>Turen startet automatisk efter tidsplanen</span><time> · ${date(trip.startedAt)}</time></span>`:trip.boardingSource==='schedule'?`<span class="automatic-arrival-note"><i class="bi bi-clock-history"></i><span>Check-in åbnet automatisk én time før afgang</span><time> · ${date(trip.boardingStartedAt)}</time></span>`:`<span>Check-in åbner automatisk én time før afgang · ${date(checkInOpensAt)}</span>`;
  return`<section class="operational-lifecycle ${phase}"><header><div><small>TURENS LIVSCYKLUS</small><strong>${operationalPhaseLabels[phase]||'Planlagt'}</strong>${lifecycleNote}</div><div class="operational-lifecycle-action">${action}</div></header><div class="operational-steps">${operationalPhaseOrder.map((step,index)=>`<div class="${lifecycleStepState(phase,step)}"><i>${lifecycleStepState(phase,step)==='done'?'<span class="bi bi-check-lg"></span>':index+1}</i><span>${operationalPhaseLabels[step]}</span></div>`).join('')}</div></section>`
}
async function applyOperationalAction(action){const trip=state.trip.trip;try{const updated=await api(`/api/trips/${trip.id}`,{method:'PATCH',body:JSON.stringify({operationalAction:action})});state.trip.trip=updated;Object.assign(state.trips.find(item=>item.id===trip.id)||{},updated);toast(action==='start_boarding'?'Check-in er åbnet':action==='start_trip'?'Turen er startet':'Ankomsten er registreret');renderTrip()}catch(error){if(error.blockers?.departureChecklist){state.tab='departure';toast(`${error.blockers.departureChecklist.length} afgangskontroller mangler`);renderTrip()}else toast(error.message)}}
const renderTripBeforeOperationalLifecycle=renderTrip;
renderTrip=function(){renderTripBeforeOperationalLifecycle();const trip=state.trip?.trip,hero=$('.detail-hero');if(!trip||!hero||trip.status==='cancelled')return;hero.insertAdjacentHTML('afterend',operationalLifecyclePanel(trip));$$('[data-operational-action]').forEach(button=>button.onclick=()=>applyOperationalAction(button.dataset.operationalAction));$('[data-close-operations]')?.addEventListener('click',showCloseTripDialog);$('[data-open-departure]')?.addEventListener('click',()=>{state.tab='departure';renderTrip()});$('[data-open-checkin]')?.addEventListener('click',()=>{state.tab='checkin';state.checkInAllPassengers=true;renderTrip()})};

function actionCenterMarkup(items=[]){
  const critical=items.filter(item=>item.severity==='critical').length;
  return`<section class="operations-action-center"><header><div><small><i class="bi bi-exclamation-diamond-fill"></i> SAMLET DRIFTSKONTROL</small><h3>Alt der kræver handling</h3><p>Ingen tur kan falde mellem to stole. Åbn opgaven direkte herfra.</p></div><span class="${critical?'critical':'clear'}">${critical?`${critical} kritiske`:'Ingen kritiske'}</span></header><div class="operations-action-list">${items.length?items.slice(0,12).map(item=>`<button data-action-trip="${item.tripId}" data-action-target="${item.target}" class="${item.severity}"><i class="bi ${item.key==='passengers'||item.key==='passenger-close'?'bi-people-fill':item.key==='baggage'?'bi-luggage-fill':item.key==='receipts'||item.key==='expense-approval'?'bi-receipt-cutoff':item.key==='departure'?'bi-clipboard2-check-fill':'bi-cash-stack'}"></i><span><small>${esc(item.tripTitle)} · ${date(item.departureAt)}</small><strong>${esc(item.title)}</strong><em>${esc(item.message)}</em></span><b>${item.count||'!'}</b><i class="bi bi-arrow-right"></i></button>`).join(''):'<div class="operations-all-clear"><i class="bi bi-shield-check"></i><span><strong>Alt er under kontrol</strong><small>Der er ingen åbne driftsproblemer på dine ture.</small></span></div>'}</div></section>`
}
