// Payments promised in Denmark or Macedonia are confirmed separately from cash
// handled in the bus. They therefore count as revenue without entering a cash box.
function externalPaymentDisplay(record){
  if(!record?.externalPaymentConfirmedAt)return null;
  const country=record.paymentStatus==='pay_mk'?'MK':'DK';
  return{country,label:`Betalt i ${country}`,amount:Number(record.externalPaymentAmount||0),currency:record.externalPaymentCurrency||record.paymentCurrency||'DKK',by:record.externalPaymentConfirmedByName||record.paymentRecordedByName||'Ukendt medarbejder'};
}
function openExternalPaymentDialog(kind,id){
  const collection=kind==='passenger'?state.trip.passengers:state.trip.baggage,record=collection.find(item=>item.id===Number(id));if(!record)return;
  if(!['admin','sales_manager'].includes(state.user.role))return toast('Kun administratoren eller en salgschef kan bekræfte betalingen');
  const isPassenger=kind==='passenger',country=record.paymentStatus==='pay_mk'?'Makedonien':'Danmark',name=isPassenger?record.name:record.senderName;
  $('#modalBody').innerHTML=`<section class="external-payment-dialog"><header><span><i class="bi bi-patch-check-fill" aria-hidden="true"></i></span><div><small>EKSTERN BETALINGSBEKRÆFTELSE</small><h2>Bekræft betaling i ${country}</h2><p>${esc(name)} · ${isPassenger?'billet':'bagage'}</p></div></header><form class="form" id="externalPaymentForm"><label>Modtaget beløb<input name="amount" type="number" min="0.01" step="0.01" required autofocus></label><label>Valuta<select name="currency"><option value="DKK">DKK</option><option value="EUR">EUR</option></select></label><label class="wide">Reference eller bemærkning<textarea name="note" placeholder="Fx betalingsreference, butik eller medarbejder"></textarea></label><div class="external-payment-info wide"><i class="bi bi-info-circle-fill" aria-hidden="true"></i><span><strong>Pengene registreres som betalt i ${country}</strong><small>Beløbet tæller med i salget, men lægges ikke i chaufførens eller salgschefens kontantkasse.</small></span></div><button class="primary wide"><i class="bi bi-check2-circle" aria-hidden="true"></i> Bekræft betaling</button></form></section>`;
  const dialog=$('#modal');dialog.classList.add('external-payment-modal');dialog.addEventListener('close',()=>dialog.classList.remove('external-payment-modal'),{once:true});
  $('#externalPaymentForm').onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));try{const updated=await api(`/api/trips/${state.trip.trip.id}/${isPassenger?'passengers':'baggage'}`,{method:'PATCH',body:JSON.stringify({id:record.id,confirmExternalPayment:true,amount:Number(data.amount),currency:data.currency,note:data.note})});Object.assign(record,updated);dialog.classList.remove('external-payment-modal');dialog.close();toast(`Betalingen i ${country} er bekræftet`);renderTrip()}catch(error){toast(error.message)}};
  translateElement($('#modalBody'));dialog.showModal();
}

function enhanceExternalBaggagePayments(){
  if(state.tab!=='baggage')return;
  $$('#tabContent [data-bag]').forEach(control=>{
    const item=state.trip.baggage.find(record=>record.id===Number(control.dataset.bag)),row=control.closest('tr');if(!item||!row)return;
    const paymentHeading=[...row.closest('table')?.querySelectorAll('thead th')||[]].findIndex(cell=>cell.textContent.trim()==='Betaling'),cell=paymentHeading>=0?row.cells[paymentHeading]:null;if(!cell)return;
    const confirmed=externalPaymentDisplay(item);
    if(confirmed){cell.innerHTML=`<span class="external-payment-confirmed"><i class="bi bi-patch-check-fill" aria-hidden="true"></i><span><strong>${esc(confirmed.label)}</strong><small>${money(confirmed.amount,confirmed.currency)} · ${esc(confirmed.by)}</small></span></span>`;return;}
    if(['pay_dk','pay_mk'].includes(item.paymentStatus)){
      const country=item.paymentStatus==='pay_mk'?'MK':'DK';cell.innerHTML=`<span class="external-payment-pending"><strong>Betaler i ${country}</strong><small>Afventer bekræftelse</small></span>${['admin','sales_manager'].includes(state.user.role)?`<button type="button" class="mini external-confirm-button" data-confirm-external-baggage="${item.id}"><i class="bi bi-patch-check" aria-hidden="true"></i> Bekræft</button>`:''}`;
    }
  });
  $$('[data-confirm-external-baggage]').forEach(button=>button.onclick=()=>openExternalPaymentDialog('baggage',Number(button.dataset.confirmExternalBaggage)));
}
const renderTabBeforeExternalPayment=renderTab;
renderTab=function(){renderTabBeforeExternalPayment();enhanceExternalBaggagePayments()};

