const checkinCardBeforePartyBookings=checkinCard;
checkinCard=function(passenger){let html=checkinCardBeforePartyBookings(passenger);if(!passenger.partyBookingId)return html;const label=passenger.partyRole==='primary'?`Hovedperson · ${passenger.partySize} personer`:'Gruppemedlem';html=html.replace(`<span>${esc(passenger.name)}</span>`,`<span>${esc(passenger.name)}</span><em class="party-booking-badge ${passenger.partyRole==='primary'?'':'member'}">${label}</em>`);if(passenger.paymentStatus==='group_included')html=html.replace('<div class="checkin-payment unpaid"><small>Ikke betalt</small><strong>Betaling mangler</strong></div>','<div class="checkin-payment paid"><small>Gruppebooking</small><strong>Fælles betaling</strong></div>');if(passenger.partyRole==='member'&&passenger.partyContactPhone){html=html.replaceAll('href="tel:"',`href="tel:${esc(passenger.partyContactPhone)}"`).replace('aria-label="Ring til '+esc(passenger.name)+'"',`aria-label="Ring til ${esc(passenger.partyContactName||'hovedpersonen')}"`)}return html};
const showPassengerDetailBeforePartyBookings=showPassengerDetail;
showPassengerDetail=function(id){showPassengerDetailBeforePartyBookings(id);const passenger=state.trip.passengers.find(item=>item.id===id);if(!passenger?.partyBookingId)return;const list=$('.detail-list'),phoneRow=[...$$('.detail-list>div')].find(row=>row.querySelector('span')?.textContent==='Telefon'),paymentRow=[...$$('.detail-list>div')].find(row=>row.querySelector('span')?.textContent==='Betaling');phoneRow?.insertAdjacentHTML('beforebegin',`<div class="party-detail"><span>Gruppebooking</span><strong>${passenger.partyRole==='primary'?`Hovedperson · ${passenger.partySize} personer`:`Gruppemedlem<small>Kontakt: ${esc(passenger.partyContactName||'hovedpersonen')}</small>`}</strong></div>`);if(passenger.partyRole==='member'&&phoneRow)phoneRow.querySelector('strong').innerHTML=passenger.partyContactPhone?`<a href="tel:${esc(passenger.partyContactPhone)}">${esc(passenger.partyContactPhone)}</a><small class="audit-note">Hovedpersonens telefonnummer</small>`:'Kontakt hovedpersonen';if(paymentRow&&passenger.paymentStatus==='group_included')paymentRow.querySelector('strong').textContent='Dækket af gruppens fælles betaling';if(list&&!list.querySelector('.party-detail'))list.insertAdjacentHTML('afterbegin','')};
const showPassengerActionSheetBeforePartyBookings=showPassengerActionSheet;
showPassengerActionSheet=function(id){showPassengerActionSheetBeforePartyBookings(id);const passenger=state.trip.passengers.find(item=>item.id===id);if(!passenger?.partyBookingId)return;$('.passenger-action-sheet header h2')?.insertAdjacentHTML('afterend',`<span class="party-booking-badge ${passenger.partyRole==='primary'?'':'member'}">${passenger.partyRole==='primary'?`Hovedperson · ${passenger.partySize} personer`:'Gruppemedlem'}</span>`);if(passenger.partyRole==='member'&&passenger.partyContactPhone){const call=$('.passenger-action-grid a[href^="tel:"]');if(call){call.href=`tel:${passenger.partyContactPhone}`;const small=call.querySelector('small');if(small)small.textContent=`${passenger.partyContactName||'Hovedperson'} · ${passenger.partyContactPhone}`}}};
const showPassengerCorrectionBeforePartyBookings=showPassengerCorrection;
