// Trinvis billetbestilling med enkeltbillet, fast retur og åben retur.
function tripHasBookingStop(trip,stopId){return Number(trip.originId)===Number(stopId)||Number(trip.destinationId)===Number(stopId)||(trip.timetable||[]).some(row=>Number(row.stopId)===Number(stopId))}
function returnTripCandidates(pickupStopId,destinationStopId){const current=state.trip?.trip;if(!current)return[];return(state.trips||[]).filter(trip=>trip.id!==current.id&&!['cancelled','completed'].includes(trip.status)&&new Date(trip.departureAt)>new Date(current.departureAt)&&tripHasBookingStop(trip,destinationStopId)&&tripHasBookingStop(trip,pickupStopId)).sort((a,b)=>new Date(a.departureAt)-new Date(b.departureAt))}
function bookingPaymentOptions(){const values=state.user.role==='driver'?[['cash','Betalt kontant i bussen']]:state.user.role==='sales_manager'?[['unpaid','Ikke betalt'],['pay_dk','Betaler i DK'],['pay_mk','Betaler i MK'],['cash','Betalt kontant']]:[['unpaid','Ikke betalt'],['pay_dk','Betaler i DK'],['pay_mk','Betaler i MK'],['cash','Betalt kontant'],['free','Gratis billet']];return values.map(([value,label],index)=>`<option value="${value}" ${index===0?'selected':''}>${label}</option>`).join('')}
function bookingTicketLabel(type){return{one_way:'Enkeltbillet',return_fixed:'Returbillet · fast dato',return_open:'Åben returbillet'}[type]||'Enkeltbillet'}
function bookingReturnTripOptions(pickupStopId,destinationStopId){const trips=returnTripCandidates(pickupStopId,destinationStopId);return`<option value="">${trips.length?'Vælg returtur':'Ingen passende returture er oprettet endnu'}</option>${trips.map(trip=>`<option value="${trip.id}">${esc(trip.title)} · ${date(trip.departureAt)}</option>`).join('')}`}

