  const showStep=value=>{step=Math.max(1,Math.min(4,value));steps.forEach(section=>section.classList.toggle('active',Number(section.dataset.bookingStep)===step));stepButtons.forEach(button=>{const number=Number(button.dataset.bookingStepButton);button.classList.toggle('active',number===step);button.classList.toggle('complete',number<step)});back.hidden=step===1;next.hidden=step===4;submit.hidden=step!==4;position.textContent=`Trin ${step} af 4`;submit.textContent=groupEnabled()?'Opret gruppebooking':'Opret booking';form.closest('.booking-panel')?.scrollIntoView({block:'start',behavior:'smooth'})};
