  function updateSummary(){const pickup=stopName(Number(form.elements.pickupStopId.value)),destination=stopName(Number(form.elements.destinationStopId.value)),extra=form.elements.extraSeatNumber?.value,members=memberCards().map(memberData),isGroup=groupEnabled(),groupRow=form.querySelector('[data-summary-group-row]');form.querySelector('[data-summary-name]').textContent=form.elements.name.value.trim()||'Ikke angivet';groupRow.hidden=!isGroup;form.querySelector('[data-summary-group]').textContent=`${members.length+1} passagerer · fælles kontakt`;form.querySelector('[data-summary-route]').textContent=`${pickup} → ${destination}`;let ticket=bookingTicketLabel(ticketType());if(ticketType()==='return_fixed'&&form.elements.returnTripId.value){const selected=form.elements.returnTripId.selectedOptions[0];ticket+=` · ${selected?.textContent||''}`}if(ticketType()==='return_open'&&form.elements.openReturnValidUntil.value)ticket+=` · gyldig til ${form.elements.openReturnValidUntil.value}`;form.querySelector('[data-summary-ticket]').textContent=ticket;const primarySeat=form.elements.seatNumber.value?`${form.elements.name.value.trim()||'Hovedperson'}: ${form.elements.seatNumber.value}${extra?` + ${extra}`:''}${ticketType()==='return_fixed'&&form.elements.returnSeatNumber.value?` / retur ${form.elements.returnSeatNumber.value}`:''}`:'';const memberSeats=isGroup?members.filter(item=>item.seatNumber).map(item=>`${item.name||'Passager'}: ${item.seatNumber}${item.extraSeatNumber?` + ${item.extraSeatNumber}`:''}${ticketType()==='return_fixed'&&item.returnSeatNumber?` / retur ${item.returnSeatNumber}`:''}`):[];form.querySelector('[data-summary-seats]').textContent=[primarySeat,...memberSeats].filter(Boolean).join(' · ')||'Ikke valgt';const payment=form.elements.paymentStatus.selectedOptions[0]?.textContent||'Ikke betalt',amount=form.elements.paymentStatus.value==='cash'&&Number(form.elements.cashAmount.value)>0?` · ${money(form.elements.cashAmount.value,form.elements.paymentCurrency.value)}`:'';form.querySelector('[data-summary-payment]').textContent=(isGroup?'Fælles · ':'')+payment+amount}
  const validateStep=value=>{const members=memberCards().map(memberData);if(value===1){for(const input of [form.elements.name,form.elements.phone])if(!input.reportValidity())return false;if(groupEnabled()&&!members.length){toast('Tilføj mindst én ekstra passager');return false}if(groupEnabled()&&members.some(member=>!member.name)){toast('Skriv navnet på alle passagerer i gruppen');return false}}if(value===2){if(form.elements.pickupStopId.value===form.elements.destinationStopId.value){toast('Opsamlingssted og destination skal være forskellige');return false}if(ticketType()==='return_fixed'&&!form.elements.returnTripId.value){toast('Vælg en returtur');return false}if(ticketType()==='return_open'&&!form.elements.openReturnValidUntil.reportValidity())return false}if(value===3){if(!form.elements.seatNumber.value){toast('Vælg et sæde på udrejsen');return false}if(form.elements.extraSeatRequested.checked&&!form.elements.extraSeatNumber.value){toast('Vælg et hovedsæde med et ledigt nabosæde');return false}if(ticketType()==='return_fixed'&&!form.elements.returnSeatNumber.value){toast('Vælg et sæde på returturen');return false}if(groupEnabled()){if(members.some(member=>!member.seatNumber)){toast('Vælg udrejsesæde til alle gruppens passagerer');return false}const outbound=[form.elements.seatNumber.value,form.elements.extraSeatNumber?.value,...members.flatMap(member=>[member.seatNumber,member.extraSeatNumber])].filter(Boolean);if(new Set(outbound).size!==outbound.length){toast('Et sæde kan kun vælges én gang i gruppen');return false}if(ticketType()==='return_fixed'){if(members.some(member=>!member.returnSeatNumber)){toast('Vælg retursæde til alle gruppens passagerer');return false}const returns=[form.elements.returnSeatNumber.value,...members.map(member=>member.returnSeatNumber)];if(new Set(returns).size!==returns.length){toast('Et retursæde kan kun vælges én gang i gruppen');return false}}for(const member of members.filter(item=>item.extraSeatNumber&&item.extraSeatFree!=='true'))if(!(Number(member.extraSeatAmount)>0)){toast(`Angiv ekstrasædets beløb for ${member.name}`);return false}}}return true};
  next.onclick=()=>{if(validateStep(step))showStep(step+1)};back.onclick=()=>showStep(step-1);stepButtons.forEach(button=>button.onclick=()=>{const target=Number(button.dataset.bookingStepButton);if(target<step||target===step||validateStep(step))showStep(target)});
