const renderEnhancedPassengerTabBeforeBookingWizard=renderEnhancedPassengerTab;
renderEnhancedPassengerTab=function(){renderEnhancedPassengerTabBeforeBookingWizard();const form=$('#passengerForm');if(form&&state.user.role==='sales_manager'){const selected=form.elements.pickupStopId.value;form.elements.pickupStopId.innerHTML=state.stops.map(stop=>`<option value="${stop.id}" ${String(stop.id)===selected?'selected':''}>${esc(stop.name)}</option>`).join('')}$$('[data-passenger-row]').forEach(row=>{const id=Number(row.querySelector('[data-passenger-detail]')?.dataset.passengerDetail),passenger=state.trip.passengers.find(item=>item.id===id);if(!passenger)return;const cell=row.cells[0];if(passenger.journeyLeg==='return')cell?.insertAdjacentHTML('beforeend','<span class="ticket-kind return-leg">Returrejse</span>');else if(passenger.ticketType==='return_open')cell?.insertAdjacentHTML('beforeend','<span class="ticket-kind open-return">Åben retur</span>');else if(passenger.ticketType==='return_fixed')cell?.insertAdjacentHTML('beforeend','<span class="ticket-kind fixed-return">Returbillet</span>')})};

const passengerRowBeforeReturnTickets=passengerRow;
passengerRow=function(passenger){let html=passengerRowBeforeReturnTickets(passenger);if(passenger.paymentStatus==='return_included')html=html.replace(`<button class="mini payment-action" data-pay-passenger="${passenger.id}">Registrer betaling</button>`,'<span class="payment-status included">Dækket af returbillet</span>');return html};

function availableReturnTripsForPassenger(passenger){return returnTripCandidates(passenger.pickupStopId,passenger.destinationStopId)}
async function openReturnBookingDialog(passenger){const trips=availableReturnTripsForPassenger(passenger);$('#modalBody').innerHTML=`<section class="open-return-dialog"><small>ÅBEN RETURBILLET</small><h2>Book returrejse for ${esc(passenger.name)}</h2><p class="muted">Gyldig til ${passenger.openReturnValidUntil?date(passenger.openReturnValidUntil):'uden angivet dato'} · vælg en planlagt tur og et ledigt sæde.</p><form class="form" id="openReturnBookingForm"><label class="wide">Returtur<select name="returnTripId" required><option value="">${trips.length?'Vælg returtur':'Ingen passende returture'}</option>${trips.map(trip=>`<option value="${trip.id}">${esc(trip.title)} · ${date(trip.departureAt)}</option>`).join('')}</select></label><label class="wide">Sæde<select name="returnSeatNumber" required><option value="">Vælg først en returtur</option></select></label><div class="open-return-note wide"><strong>${esc(stopName(passenger.destinationStopId))} → ${esc(stopName(passenger.pickupStopId))}</strong><span>Betalingen er allerede knyttet til den oprindelige returbillet.</span></div><button class="primary wide" ${trips.length?'':'disabled'}>Bekræft returrejse</button></form></section>`;const form=$('#openReturnBookingForm');form.returnTripId.onchange=()=>loadReturnSeats(form);form.onsubmit=async event=>{event.preventDefault();try{await api(`/api/trips/${state.trip.trip.id}/passengers`,{method:'PATCH',body:JSON.stringify({id:passenger.id,bookOpenReturn:true,returnTripId:form.returnTripId.value,returnSeatNumber:form.returnSeatNumber.value})});state.trip=await api(`/api/trips/${state.trip.trip.id}`);$('#modal').close();toast('Den åbne retur er nu booket med tur og sæde');renderTrip()}catch(error){toast(error.message)}};$('#modal').showModal()}

const showPassengerDetailBeforeReturnTickets=showPassengerDetail;
showPassengerDetail=function(id){showPassengerDetailBeforeReturnTickets(id);const passenger=state.trip.passengers.find(item=>item.id===id);if(!passenger)return;const list=$('.detail-list');if(passenger.paymentStatus==='return_included'){const paymentRow=[...$$('.detail-list>div')].find(row=>row.querySelector('span')?.textContent==='Betaling');if(paymentRow)paymentRow.querySelector('strong').textContent='Dækket af den oprindelige returbillet'}if(passenger.journeyLeg==='return')list?.insertAdjacentHTML('beforeend','<div><span>Billettype</span><strong>Returrejse · betaling registreret på udrejsen</strong></div>');else if(passenger.ticketType==='return_open'){list?.insertAdjacentHTML('beforeend',`<div><span>Returbillet</span><strong>Åben retur · gyldig til ${passenger.openReturnValidUntil?date(passenger.openReturnValidUntil):'–'}</strong></div>`);list?.insertAdjacentHTML('afterend','<button class="primary book-open-return" type="button">Book returrejse nu</button>');$('.book-open-return').onclick=()=>openReturnBookingDialog(passenger)}else if(passenger.ticketType==='return_fixed'){const returnTrip=state.trips.find(item=>item.id===passenger.returnTripId);list?.insertAdjacentHTML('beforeend',`<div><span>Returbillet</span><strong>${returnTrip?`${esc(returnTrip.title)} · ${date(returnTrip.departureAt)}`:'Fast retur booket'}</strong></div>`)}};

const showPassengerActionSheetBeforeReturnTickets=showPassengerActionSheet;
showPassengerActionSheet=function(id){showPassengerActionSheetBeforeReturnTickets(id);const passenger=state.trip.passengers.find(item=>item.id===id);if(!passenger)return;if(passenger.paymentStatus==='return_included'){const payment=[...$$('.passenger-action-sheet header span')].find(span=>span.textContent.trim().startsWith('Betaling'));if(payment?.querySelector('b'))payment.querySelector('b').textContent='Dækket af retur'}if(passenger.ticketType==='return_open'&&passenger.returnStatus==='open'){$('.passenger-action-grid')?.insertAdjacentHTML('beforeend','<button data-sheet-action="book-return"><i>↔</i><strong>Book åben retur</strong><small>Vælg returtur og sæde</small></button>');$('[data-sheet-action="book-return"]')?.addEventListener('click',()=>{$('#modal').close();openReturnBookingDialog(passenger)})}};

