// Drivers can forward documented expense receipts to any sales manager.
const expenseCardBeforeSalesForwarding=expenseCard;
expenseCard=function(expense){let html=expenseCardBeforeSalesForwarding(expense);const canForward=state.user.role==='driver'&&expense.receiptFile&&[expense.createdBy,expense.paidByUserId].includes(state.user.id);if(canForward){const control=expense.forwardedToSalesManagerId?`<span class="expense-forwarded-badge">Sendt til ${esc(expense.forwardedToSalesManagerName)}</span>`:`<button class="mini" data-forward-expense="${expense.id}">Send bilag til salgschef</button>`;html=html.replace('<div class="expense-card-actions">',`<div class="expense-card-actions">${control}`)}if(state.user.role==='sales_manager'&&expense.forwardedToSalesManagerId===state.user.id)html=html.replace('<div class="expense-card-title">','<div class="expense-card-title"><span class="expense-forwarded-badge received">Modtaget fra chauffør</span>');return html};
