function budgetAmountFields(available){return`<div class="budget-transfer-amounts"><label>Beløb i DKK<input name="amountDKK" type="number" min="0" max="${Number(available?.DKK||0)}" step="0.01" value="0"><small>Til rådighed: ${money(available?.DKK||0,'DKK')}</small></label><label>Beløb i EUR<input name="amountEUR" type="number" min="0" max="${Number(available?.EUR||0)}" step="0.01" value="0"><small>Til rådighed: ${money(available?.EUR||0,'EUR')}</small></label></div><div class="budget-transfer-privacy"><b>✓</b><span><strong>Separat budgetoverførsel</strong><small>Chaufføren ser kun beløb, valuta, formål og kvitteringsnummer – aldrig passagerer, billetter eller bagage.</small></span></div>`}
const personalCashboxTransferPanelBeforePooledBudget=personalCashboxTransferPanel;
personalCashboxTransferPanel=function(cashbox){
  if(state.user.role!=='sales_manager')return personalCashboxTransferPanelBeforePooledBudget(cashbox);
  const incoming=cashbox.transfers.filter(item=>item.status==='pending'&&(item.toUserId||item.toDriverId)===state.user.id),tripOptions=(state.trips||[]).map(trip=>`<option value="${trip.id}">${esc(trip.title)} · ${date(trip.departureAt)}</option>`).join(''),available=cashbox.summary.available||{DKK:0,EUR:0},hasBudget=Number(available.DKK)>0||Number(available.EUR)>0;
  return`<section class="panel personal-cashbox-send pooled-budget-transfer"><div class="panel-head"><div><h2>Overfør budget til chauffør</h2><small>Indtast kun beløbet fra din samlede budgetkasse</small></div><span>Modtageren bekræfter beløbet</span></div>${incoming.map(item=>`<div class="personal-cashbox-incoming"><div><small>AFVENTER DIN BEKRÆFTELSE</small><strong>${esc(item.fromUserName||item.fromDriverName)} · ${money(item.totals.DKK,'DKK')} · ${money(item.totals.EUR,'EUR')}</strong><span>${esc(item.receiptNumber)}${item.note?` · ${esc(item.note)}`:''}</span></div><div><button class="primary" data-global-transfer-response="accepted" data-transfer-id="${item.id}">Bekræft modtaget</button><button class="mini danger" data-global-transfer-response="rejected" data-transfer-id="${item.id}">Afvis</button></div></div>`).join('')}${hasBudget&&cashbox.recipients.length?`<form id="personalCashboxTransferForm" class="personal-cashbox-send-form"><div class="personal-cashbox-send-head"><label>Chauffør<select name="toUserId" required>${cashbox.recipients.map(person=>`<option value="${person.id}">${esc(person.name)}</option>`).join('')}</select></label><label>Tilknyt tur <small>valgfrit</small><select name="tripId"><option value="">Uden bestemt tur</option>${tripOptions}</select></label></div>${budgetAmountFields(available)}<label>Formål / bemærkning<textarea name="note" placeholder="F.eks. brændstof, vejafgifter eller startbudget"></textarea></label><button class="primary">Overfør budget til chauffør</button></form>`:'<div class="empty">Der er intet disponibelt budget at overføre lige nu</div>'}</section>`;
};

const cashTransferPanelBeforePooledBudget=cashTransferPanel;
cashTransferPanel=function(){
  if(state.user.role!=='sales_manager')return cashTransferPanelBeforePooledBudget();
  const trip=state.trip.trip,transfers=state.trip.transfers||[],recipientIds=[trip.primaryDriverId,trip.secondaryDriverId].filter(Boolean),incoming=transfers.filter(item=>item.status==='pending'&&(item.toUserId||item.toDriverId)===state.user.id),outgoing=transfers.filter(item=>item.status==='pending'&&(item.fromUserId||item.fromDriverId)===state.user.id),box=(state.trip.cashBoxes||[]).find(item=>item.holderId===state.user.id),available=box?.totals||{DKK:0,EUR:0},hasBudget=Number(available.DKK)>0||Number(available.EUR)>0;
  return`<section class="cash-transfer-panel sales-budget-transfer pooled-budget-transfer"><header><div><small>SALGSCHEFENS BUDGETKASSE</small><h2>Overfør startbudget til chauffør</h2><p>Indtast et samlet budgetbeløb. Billet- og bagagekilder vises ikke i overførslen.</p></div><span class="transfer-security">✓ Kvitteringsnummer og revisionsspor</span></header>${incoming.map(item=>`<div class="incoming-transfer"><div><small>AFVENTER DIN BEKRÆFTELSE</small><strong>${esc(item.fromUserName||item.fromDriverName)} har overført ${money(item.totals.DKK,'DKK')} · ${money(item.totals.EUR,'EUR')}</strong></div></div>`).join('')}${outgoing.map(item=>`<div class="outgoing-transfer"><strong>Afventer ${esc(item.toUserName||item.toDriverName)}</strong><span>Turbudget · ${money(item.totals.DKK,'DKK')} · ${money(item.totals.EUR,'EUR')}</span></div>`).join('')}${recipientIds.length&&hasBudget?`<form class="cash-transfer-form" id="cashTransferForm"><div class="transfer-recipient"><span>Fra <b>${esc(state.user.name)}</b></span><i>→</i><label>Chauffør<select name="toDriverId" required>${recipientIds.map(id=>`<option value="${id}">${esc(tripStaffName(id))}</option>`).join('')}</select></label></div>${budgetAmountFields(available)}<label>Formål / bemærkning<textarea name="note" placeholder="F.eks. startbudget til brændstof og vejafgifter"></textarea></label><button class="primary">Overfør turbudget</button></form>`:'<div class="settlement-empty">Der er intet disponibelt budget eller ingen tildelt chauffør.</div>'}<section class="panel transfer-history"><div class="panel-head"><h3>Overførselshistorik</h3><small>${transfers.length} overførsler</small></div>${transfers.length?`<div class="table-scroll"><table class="list"><thead><tr><th>Fra / til</th><th>Beløb</th><th>Type</th><th>Status</th><th>Tidspunkt</th></tr></thead><tbody>${[...transfers].reverse().map(transferHistoryRow).join('')}</tbody></table></div>`:'<div class="empty">Ingen budgetoverførsler endnu</div>'}</section></section>`;
};

