const albanianDateWords={Mandag:'E hënë',Tirsdag:'E martë',Onsdag:'E mërkurë',Torsdag:'E enjte',Fredag:'E premte',Lørdag:'E shtunë',Søndag:'E diel',Januar:'janar',Februar:'shkurt',Marts:'mars',April:'prill',Maj:'maj',Juni:'qershor',Juli:'korrik',August:'gusht',September:'shtator',Oktober:'tetor',November:'nëntor',December:'dhjetor'};
function translatedDanishDate(text){if(currentAppLanguage!=='sq'||!/^[-., A-Za-zÆØÅæøå0-9]+$/.test(text))return null;let translated=text,changed=false;for(const [danish,albanian] of Object.entries(albanianDateWords)){const pattern=new RegExp(danish,'gi');if(!pattern.test(translated))continue;translated=translated.replace(pattern,albanian);changed=true}return changed?translated.replace(/\s+den\s+/i,' '):null}
function translatedText(value){if(currentAppLanguage==='da')return null;const text=String(value).trim(),entry=translationTable[text]||translationTableLower[text.toLocaleLowerCase('da-DK')];if(entry){const translated=entry[currentAppLanguage];return text===text.toLocaleUpperCase('da-DK')?translated.toLocaleUpperCase(appLocale()):translated}const translatedDate=translatedDanishDate(text);if(translatedDate)return translatedDate;for(const [pattern,translations] of dynamicTranslationPatterns){const match=text.match(pattern);if(match)return translations[currentAppLanguage](...match.slice(1))}return null}
function translateElement(root=document.body){if(!root||currentAppLanguage==='da')return;const nodes=[];if(root.nodeType===Node.TEXT_NODE)nodes.push(root);else{const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode())nodes.push(walker.currentNode)}for(const node of nodes){const original=node.nodeValue,trimmed=original.trim(),translated=translatedText(trimmed);if(translated)node.nodeValue=original.replace(trimmed,translated)}const elements=root.nodeType===Node.ELEMENT_NODE?[root,...(root.querySelectorAll?.('[placeholder],[title],[aria-label]')||[])]:[];for(const element of elements){for(const attribute of ['placeholder','title','aria-label']){const value=element.getAttribute?.(attribute),translated=value&&translatedText(value);if(translated)element.setAttribute(attribute,translated)}}}
function setAppLanguage(language){currentAppLanguage=['da','sq','de','en'].includes(language)?language:'da';document.documentElement.lang=currentAppLanguage;try{localStorage.setItem('busopsLanguage',currentAppLanguage)}catch(_){};translateElement(document.body)}
const languageObserver=new MutationObserver(records=>{if(currentAppLanguage==='da')return;for(const record of records)for(const node of record.addedNodes)translateElement(node)});languageObserver.observe(document.documentElement,{childList:true,subtree:true});

