async function performManualUncheck(id){const passenger=state.trip.passengers.find(item=>item.id===id);if(!passenger?.checkedIn)return toast('Passageren er ikke checket ind');try{if(!navigator.onLine)throw Error('offline');const updated=await api(`/api/trips/${state.trip.trip.id}/passengers`,{method:'PATCH',body:JSON.stringify({id,checkedIn:false})});Object.assign(passenger,updated,{pendingSync:false})}catch(error){const offline=!navigator.onLine||/fetch|network|offline|load failed/i.test(error.message);if(!offline)return toast(error.message);const pendingLocal=passenger.pendingSync&&offlineQueue().some(item=>item.id===id&&item.checkedIn===true);removeOfflineCheckIn(id);if(!pendingLocal)queueOfflineCheckIn({tripId:state.trip.trip.id,id,checkedIn:false});Object.assign(passenger,{checkedIn:false,attendanceStatus:'pending',checkedInAt:null,checkedInBy:null,checkedInByName:null,pendingSync:!pendingLocal})}if(state.lastCheckIn?.id===id)state.lastCheckIn=null;state.currentCheckinStop=passenger.pickupStopId;state.checkInListFilter='pending';toast('Check-in er fjernet · passageren står under Afventer');renderTrip()}
const showPassengerActionSheetBeforeManualUncheck=showPassengerActionSheet;
showPassengerActionSheet=function(id){showPassengerActionSheetBeforeManualUncheck(id);const passenger=state.trip.passengers.find(item=>item.id===id),grid=$('.passenger-action-grid');if(!passenger?.checkedIn||!grid)return;grid.insertAdjacentHTML('afterbegin','<button data-sheet-action="uncheck" class="warning"><i>↶</i><strong>Fjern check-in</strong><small>Flyt passageren tilbage til afventer</small></button>');grid.querySelector('[data-sheet-action="uncheck"]').onclick=()=>{$('#modal').close();performManualUncheck(id)}};

// Check-in can switch between the current pickup stop and every passenger on the trip.
function renderAllPassengerCheckIn(){
  const passengers=state.trip.passengers,checked=passengers.filter(passenger=>passenger.checkedIn).length,pending=passengers.filter(passenger=>!passenger.checkedIn&&passenger.attendanceStatus!=='no_show').length,noShow=passengers.filter(passenger=>passenger.attendanceStatus==='no_show').length,problems=passengers.filter(passenger=>isPendingPayment(passenger)||passenger.attendanceStatus==='no_show'),pct=passengers.length?Math.round(checked/passengers.length*100):0;
  const progress=$('.checkin-progress');if(progress)progress.innerHTML=`<span><b>${checked}</b> af ${passengers.length} på hele turen</span><div><i style="width:${pct}%"></i></div><small>Alle opsamlingssteder vises samlet</small>`;
  const complete=$('#completeStop');if(complete){complete.hidden=true;complete.disabled=true}
  const alerts=$$('.checkin-alerts>div strong');if(alerts[0])alerts[0].textContent=pending;if(alerts[1])alerts[1].textContent=passengers.filter(isPendingPayment).length;if(alerts[2])alerts[2].textContent=noShow;
  const toggle=$('#toggleProblems');if(toggle)toggle.textContent=`Vis ${problems.length} opmærksomhedspunkter`;
  const problemPanel=$('#problemPanel');if(problemPanel)problemPanel.innerHTML=problems.map(passenger=>`<button data-focus-passenger="${passenger.id}"><strong>${esc(passenger.name)}</strong><span>${passenger.attendanceStatus==='no_show'?'Udeblevet':paymentStatusLabel(passenger.paymentStatus)}</span></button>`).join('')||'<p>Ingen problemer på turen</p>';
  const sections=$('.checkin-sections');if(sections)sections.innerHTML=checkinSection('Afventer',passengers.filter(passenger=>!passenger.checkedIn&&passenger.attendanceStatus!=='no_show'),'pending')+checkinSection('Checket ind',passengers.filter(passenger=>passenger.checkedIn),'checked')+checkinSection('Udeblevet',passengers.filter(passenger=>passenger.attendanceStatus==='no_show'),'noshow');
}
const renderCheckInBeforeAllPassengers=renderCheckInMode;
renderCheckInMode=function(){
  renderCheckInBeforeAllPassengers();
  const select=$('#checkinStop');if(!select)return;
  select.insertAdjacentHTML('afterbegin',`<option value="all" ${state.checkInAllPassengers?'selected':''}>Alle passagerer · hele turen</option>`);
  if(state.checkInAllPassengers){
    select.value='all';select.closest('div')?.querySelector('.current-stop-time')?.remove();renderAllPassengerCheckIn();
    const stopIds=[...new Set(state.trip.passengers.map(passenger=>passenger.pickupStopId))];wireCheckInMode(stopIds);
    $$('[data-passenger-actions]').forEach(button=>button.onclick=()=>showPassengerActionSheet(Number(button.dataset.passengerActions)));
    $$('[data-checkin-card]').forEach(card=>{const passenger=state.trip.passengers.find(item=>item.id===Number(card.dataset.checkinCard));if(passenger?.ticketNumber)card.dataset.search=`${card.dataset.search||''} ${passenger.ticketNumber.toLowerCase()}`});
    setupCheckInListFilters();
  }
  select.onchange=event=>{state.checkInAllPassengers=event.target.value==='all';if(!state.checkInAllPassengers)state.currentCheckinStop=Number(event.target.value);renderTrip()};
};
const openTripBeforeAllPassengerCheckIn=openTrip;
openTrip=async function(id){state.checkInAllPassengers=false;return openTripBeforeAllPassengerCheckIn(id)};

// Assigned drivers must actively resolve every passenger before confirming the passenger list.
function showDriverPassengerListClosure(){
  const trip=state.trip.trip,passengers=state.trip.passengers,pending=passengers.filter(passenger=>!passenger.checkedIn&&passenger.attendanceStatus!=='no_show');
  if(pending.length){state.tab='checkin';state.checkInAllPassengers=true;state.checkInListFilter='pending';toast(`${pending.length} passagerer mangler stadig behandling`);renderTrip();return}
  $('#modalBody').innerHTML=`<section class="driver-close-dialog"><i class="bi bi-person-check-fill"></i><small>CHAUFFØRENS AFSLUTNINGSKONTROL</small><h2>Afslut passagerlisten?</h2><p>Alle ${passengers.length} passagerer er nu enten checket ind eller markeret som udeblevet. Bekræftelsen gemmes med dit navn og tidspunkt.</p><form id="driverPassengerListCloseForm" class="form"><label class="wide">Bemærkning<textarea name="note" placeholder="Valgfri intern bemærkning"></textarea></label><button class="primary wide"><i class="bi bi-check2-circle"></i> Bekræft og afslut passagerlisten</button></form></section>`;
  $('#driverPassengerListCloseForm').onsubmit=async event=>{event.preventDefault();try{const updated=await api(`/api/trips/${trip.id}`,{method:'PATCH',body:JSON.stringify({passengerListClosed:true,note:event.target.note.value})});state.trip.trip=updated;Object.assign(state.trips.find(item=>item.id===trip.id)||{},updated);$('#modal').close();toast('Passagerlisten er afsluttet og dokumenteret');renderTrip()}catch(error){const missing=error.blockers?.passengers||[];if(missing.length){$('#modal').close();state.tab='checkin';state.checkInAllPassengers=true;state.checkInListFilter='pending';toast(`${missing.length} passagerer mangler stadig behandling`);renderTrip()}else toast(error.message)}};
  $('#modal').showModal();
}
const renderTripBeforeDriverPassengerClosure=renderTrip;
renderTrip=function(){
  renderTripBeforeDriverPassengerClosure();
  const trip=state.trip?.trip;if(state.user.role!=='driver'||!trip||['cancelled','completed'].includes(trip.status))return;
  const passengers=state.trip.passengers,checked=passengers.filter(passenger=>passenger.checkedIn).length,noShow=passengers.filter(passenger=>passenger.attendanceStatus==='no_show').length,pending=passengers.length-checked-noShow,changedAfterClose=trip.passengerListClosedAt&&passengers.some(passenger=>(passenger.attendanceHistory||[]).some(event=>new Date(event.at)>new Date(trip.passengerListClosedAt))),closed=Boolean(trip.passengerListClosedAt)&&!pending&&!changedAfterClose;
  const panel=`<section class="driver-passenger-close ${closed?'is-closed':pending?'has-pending':'is-ready'}"><div class="driver-close-icon"><i class="bi ${closed?'bi-shield-check':'bi-clipboard2-check'}"></i></div><div class="driver-close-copy"><small>CHAUFFØRENS PASSAGERKONTROL</small><strong>${closed?'Passagerlisten er afsluttet':pending?'Passagerlisten kræver handling':'Alle passagerer er behandlet'}</strong><span>${closed?`${date(trip.passengerListClosedAt)} · ${esc(trip.passengerListClosedByName||state.user.name)}`:pending?'Turen kan ikke afsluttes, før alle passagerer har en status.':'Listen er klar til din endelige bekræftelse.'}</span></div><div class="driver-close-counts"><span><b>${checked}</b><small>Checket ind</small></span><span><b>${noShow}</b><small>Udeblevet</small></span><span class="${pending?'attention':''}"><b>${pending}</b><small>Afventer</small></span></div><div class="driver-close-action">${closed?'<span class="driver-close-confirmed"><i class="bi bi-check2-circle"></i> Dokumenteret</span>':pending?`<button class="btn btn-warning" id="showPendingPassengers"><i class="bi bi-people"></i> Vis ${pending} manglende</button>`:'<button class="btn btn-success" id="closePassengerList"><i class="bi bi-check2-circle"></i> Afslut passagerlisten</button>'}</div></section>`;
  const anchor=$('.trip-cancelled-banner')||$('.trip-closed-banner')||$('.detail-hero');anchor?.insertAdjacentHTML('afterend',panel);
  $('#showPendingPassengers')?.addEventListener('click',()=>{state.tab='checkin';state.checkInAllPassengers=true;state.checkInListFilter='pending';renderTrip()});
  $('#closePassengerList')?.addEventListener('click',showDriverPassengerListClosure);
};

// PDF-billetter, billedoptimering og en fælles offlinekø til den mobile drift.
function openTicketPdf(bookingNumber,reprint=false){
  if(!bookingNumber)return toast('Bookingen har endnu ikke et bookingnummer');
  if(!navigator.onLine)return toast('PDF-billetten kan hentes, når enheden er online');
  const url=`/api/bookings/${encodeURIComponent(bookingNumber)}/ticket.pdf?download=1${reprint?'&reprint=1':''}`;window.open(url,'_blank','noopener');
}

function blobAsDataUrl(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Filen kunne ikke læses'));reader.readAsDataURL(blob)})}
function canvasBlob(canvas,type,quality){return new Promise(resolve=>canvas.toBlob(resolve,type,quality))}
async function optimizeUploadImage(file,{maxDimension=2048,maxBytes=2*1024*1024}={}){
  if(!file?.type?.startsWith('image/'))return{name:file?.name,type:file?.type,data:await fileAsDataUrl(file),originalBytes:file?.size||0,storedBytes:file?.size||0,optimized:false};
  let bitmap;try{bitmap=await createImageBitmap(file)}catch(_){const url=URL.createObjectURL(file);bitmap=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=reject;image.src=url}).finally(()=>URL.revokeObjectURL(url))}
  const scale=Math.min(1,maxDimension/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext('2d',{alpha:false});context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();
  let quality=.84,blob=await canvasBlob(canvas,'image/jpeg',quality);while(blob&&blob.size>maxBytes&&quality>.48){quality-=.08;blob=await canvasBlob(canvas,'image/jpeg',quality)}
  if(!blob)throw Error('Billedet kunne ikke optimeres');if(blob.size>=file.size&&file.size<=maxBytes)return{name:file.name,type:file.type,data:await fileAsDataUrl(file),originalBytes:file.size,storedBytes:file.size,optimized:false};
  return{name:file.name.replace(/\.[^.]+$/,'.jpg'),type:'image/jpeg',data:await blobAsDataUrl(blob),originalBytes:file.size,storedBytes:blob.size,optimized:true};
}
function optimizedMessage(result,label){if(!result.optimized)return`${label} er gemt`;const before=(result.originalBytes/1048576).toFixed(1),after=(result.storedBytes/1048576).toFixed(1);return`${label} er optimeret fra ${before} MB til ${after} MB og gemt`}

uploadExpense=async function(event){event.preventDefault();const form=event.target,file=form.receipt.files[0];if(file?.type==='application/pdf'&&file.size>5*1024*1024)return toast('PDF-kvitteringen må højst fylde 5 MB');try{const payload={category:form.category.value,amount:form.amount.value,currency:form.currency.value,paymentMethod:form.paymentMethod.value,paidByUserId:form.paidByUserId.value,description:form.description.value};let optimized=null;if(file){optimized=file.type.startsWith('image/')?await optimizeUploadImage(file):{name:file.name,type:file.type,data:await fileAsDataUrl(file),originalBytes:file.size,storedBytes:file.size,optimized:false};Object.assign(payload,{receiptName:optimized.name,receiptType:optimized.type,receiptData:optimized.data,receiptOriginalBytes:optimized.originalBytes,receiptStoredBytes:optimized.storedBytes,receiptOptimized:optimized.optimized})}const expense=await api(`/api/trips/${state.trip.trip.id}/expenses`,{method:'POST',body:JSON.stringify(payload)});state.trip.expenses.push(expense);toast(file?optimizedMessage(optimized,'Udgiften og kvitteringen'):'Udgiften er gemt · kvittering mangler');renderTrip()}catch(error){toast(error.message)}};
attachExpenseReceipt=async function(id,file){if(!file)return;if(file.type==='application/pdf'&&file.size>5*1024*1024)return toast('PDF-kvitteringen må højst fylde 5 MB');try{const optimized=file.type.startsWith('image/')?await optimizeUploadImage(file):{name:file.name,type:file.type,data:await fileAsDataUrl(file),originalBytes:file.size,storedBytes:file.size,optimized:false},updated=await api(`/api/expenses/${id}`,{method:'PATCH',body:JSON.stringify({receiptName:optimized.name,receiptType:optimized.type,receiptData:optimized.data,receiptOriginalBytes:optimized.originalBytes,receiptStoredBytes:optimized.storedBytes,receiptOptimized:optimized.optimized})});Object.assign(state.trip.expenses.find(item=>item.id===id),updated);toast(optimizedMessage(optimized,'Kvitteringen'));renderTrip()}catch(error){toast(error.message)}};
wireBaggageForm=function(){const form=$('#baggageForm'),photoInput=form.elements.photo,photoLabel=form.querySelector('.baggage-photo-capture b');photoInput.onchange=()=>{photoLabel.textContent=photoInput.files[0]?.name||'Tag billede eller vælg foto'};form.onsubmit=async event=>{event.preventDefault();const file=photoInput.files[0];if(!file)return toast('Tag eller vælg et billede af bagagen');if(!['image/jpeg','image/png','image/webp'].includes(file.type))return toast('Bagagebilledet skal være JPG, PNG eller WebP');try{photoLabel.textContent='Optimerer billede …';const optimized=await optimizeUploadImage(file),payload=Object.fromEntries(new FormData(form));delete payload.photo;Object.assign(payload,{photoName:optimized.name,photoType:optimized.type,photoData:optimized.data,photoOriginalBytes:optimized.originalBytes,photoStoredBytes:optimized.storedBytes,photoOptimized:optimized.optimized});const baggage=await api(`/api/trips/${state.trip.trip.id}/baggage`,{method:'POST',body:JSON.stringify(payload)});state.trip.baggage.push(baggage);toast(baggage.__offlineQueued?'Bagagen er gemt offline og synkroniseres automatisk':optimizedMessage(optimized,'Bagagen og billeddokumentationen'));renderTrip()}catch(error){photoLabel.textContent=file.name;toast(error.message)}}};

var offlineQueueCache=[],offlineSyncRunning=false;
function offlineQueue(){return offlineQueueCache}
function offlineId(){return globalThis.crypto?.randomUUID?.()||`offline-${Date.now()}-${Math.random().toString(16).slice(2)}`}
function offlineDeviceId(){let value=localStorage.getItem('busops-device-id');if(!value){value=offlineId();localStorage.setItem('busops-device-id',value)}return value}
function queueableOfflineMutation(path,options){const method=String(options?.method||'GET').toUpperCase();return['POST','PATCH'].includes(method)&&/^\/api\/trips\/\d+\/(passengers|group-bookings|baggage)$/.test(path)}
function isNetworkFailure(error){return!navigator.onLine||/fetch|network|offline|load failed|failed to fetch/i.test(String(error?.message||''))}
function offlineActionLabel(path,method,payload){if(path.endsWith('/group-bookings'))return'Gruppebooking';if(path.endsWith('/passengers'))return method==='POST'?`Billet · ${payload.name||'ny passager'}`:payload.paymentStatus==='cash'?'Billetbetaling':typeof payload.checkedIn==='boolean'?(payload.checkedIn?'Check-in':'Fjern check-in'):payload.attendanceStatus==='no_show'?'Udeblevet':'Passagerændring';if(path.endsWith('/baggage'))return method==='POST'?`Bagage · ${payload.senderName||'ny forsendelse'}`:payload.paymentStatus==='cash'?'Bagagebetaling':`Bagagestatus · ${payload.status||'ændring'}`;return'Offlinehandling'}
function optimisticOfflineResponse(path,method,payload,clientActionId){const tripId=Number(path.match(/\/trips\/(\d+)/)?.[1]),base={__offlineQueued:true,pendingSync:true,clientActionId};if(path.endsWith('/group-bookings')){const partyBookingId=`offline-${clientActionId}`,passengers=(payload.passengers||[]).map((item,index)=>({...payload,...item,id:-Date.now()-index,tripId,phone:index?'' : payload.phone,partyBookingId,partyRole:index?'member':'primary',partySize:payload.passengers.length,checkedIn:false,attendanceStatus:'pending',bookingNumber:'Afventer synkronisering',pendingSync:true}));return{...base,partyBookingId,partySize:passengers.length,passengers}}if(path.endsWith('/passengers')){if(method==='POST')return{...payload,...base,id:-Date.now(),tripId,seatNumber:Number(payload.seatNumber),pickupStopId:Number(payload.pickupStopId),destinationStopId:Number(payload.destinationStopId),checkedIn:false,attendanceStatus:'pending',bookingNumber:'Afventer synkronisering'};const current=state.trip?.passengers?.find(item=>item.id===Number(payload.id))||{};return{...current,...payload,...base,checkedIn:typeof payload.checkedIn==='boolean'?payload.checkedIn:current.checkedIn,attendanceStatus:payload.attendanceStatus==='no_show'?'no_show':typeof payload.checkedIn==='boolean'?(payload.checkedIn?'checked_in':'pending'):current.attendanceStatus,paymentStatus:payload.paymentStatus||current.paymentStatus,cashAmount:payload.paymentStatus==='cash'?Number(payload.cashAmount):current.cashAmount,paymentCurrency:payload.paymentCurrency||current.paymentCurrency}}
  if(path.endsWith('/baggage')){if(method==='POST')return{...payload,...base,id:-Date.now(),tripId,pieces:Number(payload.pieces),pickupStopId:Number(payload.pickupStopId),destinationStopId:Number(payload.destinationStopId),status:'registered'};const current=state.trip?.baggage?.find(item=>item.id===Number(payload.id))||{};return{...current,...payload,...base,paymentStatus:payload.paymentStatus||current.paymentStatus,cashAmount:payload.paymentStatus==='cash'?Number(payload.cashAmount):current.cashAmount}}
  return base}
async function updateOfflineState(){offlineQueueCache=await BusOpsOffline.list();renderOfflineIndicator();if(navigator.onLine)reportOfflineStatus()}
async function enqueueOfflineAction(path,options,payload,clientActionId){const action={id:clientActionId,path,method:String(options.method).toUpperCase(),body:JSON.stringify({...payload,clientActionId}),label:offlineActionLabel(path,String(options.method).toUpperCase(),payload),status:'pending',createdAt:new Date().toISOString(),attempts:0,lastError:''};await BusOpsOffline.put(action);await updateOfflineState();const optimistic=optimisticOfflineResponse(path,action.method,payload,clientActionId);const reserve=passenger=>[passenger.seatNumber,passenger.extraSeatNumber].filter(Boolean).forEach(number=>{const seat=state.trip?.seats?.find(item=>item.number===Number(number));if(seat)seat.passengerId=passenger.id});if(action.method==='POST'&&state.trip&&path.endsWith('/passengers')){state.trip.passengers.push(optimistic);reserve(optimistic)}if(action.method==='POST'&&state.trip&&path.endsWith('/group-bookings')){state.trip.passengers.push(...optimistic.passengers);optimistic.passengers.forEach(reserve)}return optimistic}
const apiBeforeOfflineQueue=api;
api=async function(path,options={}){if(!navigator.onLine&&(!options.method||options.method==='GET')&&state.trip&&path===`/api/trips/${state.trip.trip.id}`)return state.trip;if(!queueableOfflineMutation(path,options))return apiBeforeOfflineQueue(path,options);let payload={};try{payload=JSON.parse(options.body||'{}')}catch(_){return apiBeforeOfflineQueue(path,options)}const clientActionId=payload.clientActionId||offlineId(),request={...options,body:JSON.stringify({...payload,clientActionId})};if(!navigator.onLine)return enqueueOfflineAction(path,request,payload,clientActionId);try{return await apiBeforeOfflineQueue(path,request)}catch(error){if(!isNetworkFailure(error))throw error;return enqueueOfflineAction(path,request,payload,clientActionId)}};
function queueOfflineCheckIn(item){return enqueueOfflineAction(`/api/trips/${item.tripId}/passengers`,{method:'PATCH'},item,offlineId())}
function removeOfflineCheckIn(id){offlineQueueCache.filter(item=>Number(JSON.parse(item.body||'{}').id)===Number(id)).forEach(item=>BusOpsOffline.remove(item.id));updateOfflineState()}
async function replayOfflineAction(action){const response=await fetch(action.path,{method:action.method,headers:{'Content-Type':'application/json'},body:action.body});let data={};try{data=await response.json()}catch(_){}if(!response.ok){const error=Error(data.error||`Synkronisering fejlede (${response.status})`);error.status=response.status;throw error}return data}
async function syncOfflineActions(){if(!navigator.onLine||offlineSyncRunning)return;offlineSyncRunning=true;try{const actions=await BusOpsOffline.list();for(const action of actions.filter(item=>item.status!=='conflict')){try{await replayOfflineAction(action);await BusOpsOffline.remove(action.id)}catch(error){action.attempts=Number(action.attempts||0)+1;action.lastError=error.message;action.lastAttemptAt=new Date().toISOString();if(error.status&&error.status<500)action.status='conflict';await BusOpsOffline.put(action);if(!navigator.onLine)break}}await updateOfflineState();if(actions.length&&!offlineQueueCache.length)toast('Alle offlinehandlinger er synkroniseret');if(state.trip&&navigator.onLine&&actions.some(item=>Number(item.path.match(/\/trips\/(\d+)/)?.[1])===state.trip.trip.id)){try{state.trip=await apiBeforeOfflineQueue(`/api/trips/${state.trip.trip.id}`);renderTrip()}catch(_){}}}finally{offlineSyncRunning=false}}
function syncOfflineCheckIns(){return syncOfflineActions()}
async function reportOfflineStatus(){if(!state.user||!navigator.onLine)return;const conflicts=offlineQueueCache.filter(item=>item.status==='conflict').length;try{await fetch('/api/offline/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({deviceId:offlineDeviceId(),pendingCount:offlineQueueCache.length,conflictCount:conflicts,label:navigator.userAgent})})}catch(_){}}
function renderOfflineIndicator(){let indicator=$('#offlineSyncIndicator');if(!indicator){indicator=document.createElement('button');indicator.id='offlineSyncIndicator';indicator.type='button';document.querySelector('.content>header')?.append(indicator);indicator.onclick=showOfflineQueue}if(!indicator)return;const conflicts=offlineQueueCache.filter(item=>item.status==='conflict').length,needsAttention=!navigator.onLine||offlineQueueCache.length>0||conflicts>0;indicator.hidden=!needsAttention;if(!needsAttention)return;indicator.className=`offline-sync-indicator ${navigator.onLine?'online':'offline'} ${conflicts?'conflict':''}`;indicator.innerHTML=`<i class="bi ${conflicts?'bi-exclamation-octagon-fill':offlineQueueCache.length?'bi-cloud-arrow-up-fill':'bi-cloud-slash-fill'}"></i><span>${conflicts?`${conflicts} konflikt${conflicts===1?'':'er'}`:offlineQueueCache.length?`${offlineQueueCache.length} afventer`:'Offline'}</span>`}
async function showOfflineQueue(){await updateOfflineState();$('#modalBody').innerHTML=`<section class="offline-queue-dialog"><i class="bi bi-cloud-arrow-up-fill"></i><small>OFFLINE OG SYNKRONISERING</small><h2>${offlineQueueCache.length?`${offlineQueueCache.length} handlinger på enheden`:'Alt er synkroniseret'}</h2><p>Handlinger gemmes sikkert på denne enhed og sendes i rækkefølge, når forbindelsen er tilbage.</p><div>${offlineQueueCache.map(action=>`<article class="${action.status}"><span><strong>${esc(action.label)}</strong><small>${date(action.createdAt)}${action.lastError?` · ${esc(action.lastError)}`:''}</small></span><b>${action.status==='conflict'?'Kræver kontrol':'Afventer'}</b><button data-remove-offline="${action.id}" aria-label="Fjern handling"><i class="bi bi-trash3"></i></button></article>`).join('')||'<div class="empty">Ingen lokale handlinger</div>'}</div>${offlineQueueCache.length&&navigator.onLine?'<button class="btn btn-primary" data-sync-offline><i class="bi bi-arrow-repeat"></i> Prøv synkronisering nu</button>':''}</section>`;$$('[data-remove-offline]').forEach(button=>button.onclick=async()=>{if(!confirm('Fjern den lokale handling? Den bliver ikke sendt til serveren.'))return;await BusOpsOffline.remove(button.dataset.removeOffline);showOfflineQueue()});$('[data-sync-offline]')?.addEventListener('click',async()=>{await syncOfflineActions();showOfflineQueue()});$('#modal').showModal()}
async function initializeOfflineQueue(){try{const legacy=JSON.parse(localStorage.getItem('busops-checkin-queue')||'[]');for(const item of legacy){const clientActionId=offlineId();await BusOpsOffline.put({id:clientActionId,path:`/api/trips/${item.tripId}/passengers`,method:'PATCH',body:JSON.stringify({...item,clientActionId}),label:'Check-in fra tidligere offlinekø',status:'pending',createdAt:new Date().toISOString(),attempts:0,lastError:''})}if(legacy.length)localStorage.removeItem('busops-checkin-queue');await updateOfflineState();if(navigator.onLine)syncOfflineActions()}catch(error){console.warn('Offlinekøen kunne ikke startes',error)}}
window.addEventListener('online',()=>{renderOfflineIndicator();syncOfflineActions()});window.addEventListener('offline',renderOfflineIndicator);if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));initializeOfflineQueue();

