async function acknowledgeSystemEvents(){try{await api('/api/admin/system-events',{method:'PATCH',body:JSON.stringify({all:true})});toast('Systemhændelser er markeret som set');await renderOperationsCenter()}catch(error){toast(error.message)}}
async function revokeSession(key){try{await api(`/api/admin/sessions/${key}`,{method:'DELETE'});toast('Sessionen er afsluttet');await renderOperationsCenter()}catch(error){toast(error.message)}}

