const showPassengerDetailBeforeExtraSeat=showPassengerDetail;
showPassengerDetail=function(id){showPassengerDetailBeforeExtraSeat(id);const passenger=state.trip.passengers.find(item=>item.id===id);if(!passenger?.extraSeatNumber)return;const seatRow=[...$$('.detail-list>div')].find(row=>row.querySelector('span')?.textContent==='Sæde');if(seatRow)seatRow.querySelector('strong').innerHTML=`${passenger.seatNumber} · ${esc(passenger.seatType)}<small class="audit-note">Ekstra sæde ${passenger.extraSeatNumber} · ${passenger.extraSeatFree?'gratis':money(passenger.extraSeatAmount,passenger.extraSeatCurrency||passenger.paymentCurrency||'DKK')}${passenger.extraSeatReason?` · ${esc(passenger.extraSeatReason)}`:''}</small>`};
