editSalesManager=function(id){
  const manager=state.salesManagers.find(item=>item.id===id);if(!manager)return;
  $('#modalBody').innerHTML=`<h2>Rediger salgschef</h2><p class="muted">Administrator ændrer navn og salgskontor. Salgschefen ændrer selv e-mail og adgangskode under Min konto.</p><form class="form" id="editSalesManagerForm"><label class="wide">Fulde navn<input name="name" value="${esc(manager.name)}" required></label><label>Salgsbutik / kontor<input name="salesOfficeName" value="${esc(manager.salesOfficeName||'')}" placeholder="Fx Berlin-kontoret"></label><label>Land<select name="salesOfficeCountry"><option value="" ${!manager.salesOfficeCountry?'selected':''}>Ikke angivet</option><option value="DK" ${manager.salesOfficeCountry==='DK'?'selected':''}>Danmark</option><option value="DE" ${manager.salesOfficeCountry==='DE'?'selected':''}>Tyskland</option><option value="MK" ${manager.salesOfficeCountry==='MK'?'selected':''}>Makedonien</option><option value="OTHER" ${manager.salesOfficeCountry==='OTHER'?'selected':''}>Andet</option></select></label><div class="personal-login-lock wide"><i class="bi bi-lock-fill"></i><span><strong>${esc(manager.email)}</strong><small>Personlige loginoplysninger administreres af salgschefen selv</small></span></div><button class="primary wide"><i class="bi bi-check2-circle"></i> Gem profil</button></form>`;
  $('#editSalesManagerForm').onsubmit=async event=>{event.preventDefault();try{const updated=await api(`/api/sales-managers/${manager.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});Object.assign(manager,updated);state.trips.forEach(trip=>{if(trip.salesManagerId===manager.id){trip.salesManager=manager.name;trip.salesManagerOnDuty=manager.name}});$('#modal').close();toast('Salgschefens profil er opdateret');renderSalesManagers()}catch(error){toast(error.message)}};$('#modal').showModal();
};

const renderTripBeforeGlobalSalesAccess=renderTrip;
renderTrip=function(){
  const restricted=state.user?.role==='sales_manager'&&!salesManagerCanOperateCurrentTrip();
  if(restricted&&['checkin','departure'].includes(state.tab))state.tab='passengers';
  renderTripBeforeGlobalSalesAccess();
  if(state.user?.role!=='sales_manager'||!state.trip?.trip)return;
  const onDuty=salesManagerCanOperateCurrentTrip(),hero=$('.detail-hero');
  hero?.insertAdjacentHTML('afterend',onDuty?`<section class="sales-access-banner on-duty"><i class="bi bi-person-badge-fill"></i><span><strong>Salgschef på vagt</strong><small>Du kan booke på alle ture og udføre check-in og afgangsdrift på denne tur.</small></span></section>`:`<section class="sales-access-banner global-sales"><i class="bi bi-globe-europe-africa"></i><span><strong>Global salgsadgang</strong><small>Du kan booke passagerer og bagage fra alle stoppesteder. Check-in udføres af turens personale.</small></span></section>`);
  if(!onDuty){
    $('[data-checkin-tab]')?.remove();$('[data-departure-tab]')?.remove();$('[data-operational-action="start_boarding"]')?.remove();$('[data-open-checkin]')?.remove();
    $$('.bag-status').forEach(control=>{control.disabled=true;control.title='Driftsstatus ændres af turens personale'});
    $$('[data-check],[data-fast-check],[data-no-show]').forEach(control=>control.remove());
  }
};
